bool retainedDoubleEqual(double lhs, double rhs) noexcept {
    return std::memcmp(&lhs, &rhs, sizeof(double)) == 0;
}

bool retainedVariantEqual(const DRW_Variant& lhs,
                          const DRW_Variant& rhs) noexcept {
    const auto* leftColor = lhs.dwgCmColorValue();
    const auto* rightColor = rhs.dwgCmColorValue();
    if (lhs.code() != rhs.code() || lhs.type() != rhs.type()
        || lhs.isLayerRef() != rhs.isLayerRef()
        || (leftColor == nullptr) != (rightColor == nullptr))
        return false;
    if (leftColor != nullptr
        && (leftColor->method != rightColor->method
            || leftColor->flags != rightColor->flags
            || leftColor->index != rightColor->index
            || leftColor->rgb24 != rightColor->rgb24
            || leftColor->hasRgbColor != rightColor->hasRgbColor
            || leftColor->colorName != rightColor->colorName
            || leftColor->bookName != rightColor->bookName
            || leftColor->sourceVersion != rightColor->sourceVersion))
        return false;
    switch (lhs.type()) {
    case DRW_Variant::STRING:
        return lhs.content.s != nullptr && rhs.content.s != nullptr
            && *lhs.content.s == *rhs.content.s;
    case DRW_Variant::INTEGER:
        return lhs.i_val() == rhs.i_val();
    case DRW_Variant::INTEGER64:
        return lhs.i64_val() == rhs.i64_val();
    case DRW_Variant::DOUBLE:
        return retainedDoubleEqual(lhs.d_val(), rhs.d_val());
    case DRW_Variant::COORD: {
        const DRW_Coord* left = lhs.coord();
        const DRW_Coord* right = rhs.coord();
        return left != nullptr && right != nullptr
            && retainedDoubleEqual(left->x, right->x)
            && retainedDoubleEqual(left->y, right->y)
            && retainedDoubleEqual(left->z, right->z);
    }
    case DRW_Variant::BINARY: {
        const std::vector<std::uint8_t>* left = lhs.binary();
        const std::vector<std::uint8_t>* right = rhs.binary();
        return left != nullptr && right != nullptr && *left == *right;
    }
    case DRW_Variant::INVALID:
        return true;
    }
    return false;
}

bool retainedVariantListEqual(const std::list<DRW_Variant>& lhs,
                              const std::list<DRW_Variant>& rhs) noexcept {
    if (lhs.size() != rhs.size())
        return false;
    auto left = lhs.begin();
    auto right = rhs.begin();
    for (; left != lhs.end(); ++left, ++right) {
        if (!retainedVariantEqual(*left, *right))
            return false;
    }
    return true;
}

bool retainedVariantListsEqual(
    const std::list<std::list<DRW_Variant>>& lhs,
    const std::list<std::list<DRW_Variant>>& rhs) noexcept {
    if (lhs.size() != rhs.size())
        return false;
    auto left = lhs.begin();
    auto right = rhs.begin();
    for (; left != lhs.end(); ++left, ++right) {
        if (!retainedVariantListEqual(*left, *right))
            return false;
    }
    return true;
}

bool retainedTableStyleColorEqual(const DRW_TableStyleCmcColor& lhs,
                                  const DRW_TableStyleCmcColor& rhs) noexcept {
    return lhs.m_rgb == rhs.m_rgb && lhs.m_name == rhs.m_name
        && lhs.m_bookName == rhs.m_bookName
        && lhs.m_method == rhs.m_method && lhs.m_flags == rhs.m_flags
        && lhs.m_reservedIndex == rhs.m_reservedIndex;
}

bool retainedTableStyleContentEqual(
    const DRW_TableStyleContentFormat& lhs,
    const DRW_TableStyleContentFormat& rhs) noexcept {
    return lhs.m_propertyOverrideFlags == rhs.m_propertyOverrideFlags
        && lhs.m_propertyFlags == rhs.m_propertyFlags
        && lhs.m_valueDataType == rhs.m_valueDataType
        && lhs.m_valueUnitType == rhs.m_valueUnitType
        && lhs.m_valueFormatString == rhs.m_valueFormatString
        && retainedDoubleEqual(lhs.m_rotation, rhs.m_rotation)
        && retainedDoubleEqual(lhs.m_blockScale, rhs.m_blockScale)
        && lhs.m_cellAlignment == rhs.m_cellAlignment
        && lhs.m_contentColor == rhs.m_contentColor
        && retainedTableStyleColorEqual(lhs.m_contentColorCmc,
                                        rhs.m_contentColorCmc)
        && lhs.m_textStyleHandle == rhs.m_textStyleHandle
        && retainedDoubleEqual(lhs.m_textHeight, rhs.m_textHeight);
}

bool retainedTableStyleBorderEqual(const DRW_TableStyleBorder& lhs,
                                   const DRW_TableStyleBorder& rhs) noexcept {
    return lhs.m_edgeFlags == rhs.m_edgeFlags
        && lhs.m_propertyOverrideFlags == rhs.m_propertyOverrideFlags
        && lhs.m_borderType == rhs.m_borderType
        && lhs.m_color == rhs.m_color
        && lhs.m_lineWeight == rhs.m_lineWeight
        && lhs.m_lineTypeHandle == rhs.m_lineTypeHandle
        && lhs.m_visible == rhs.m_visible
        && retainedDoubleEqual(lhs.m_doubleLineSpacing,
                               rhs.m_doubleLineSpacing)
        && retainedTableStyleColorEqual(lhs.m_colorCmc, rhs.m_colorCmc);
}

bool retainedTableStyleBordersEqual(
    const std::vector<DRW_TableStyleBorder>& lhs,
    const std::vector<DRW_TableStyleBorder>& rhs) noexcept {
    if (lhs.size() != rhs.size())
        return false;
    for (std::size_t index = 0; index < lhs.size(); ++index) {
        if (!retainedTableStyleBorderEqual(lhs[index], rhs[index]))
            return false;
    }
    return true;
}

bool retainedCellStyleEqual(const DRW_TableStyleCellStyle& lhs,
                            const DRW_TableStyleCellStyle& rhs,
                            bool compareName = true,
                            bool compareStyleClass = true) noexcept {
    return lhs.m_type == rhs.m_type && lhs.m_hasData == rhs.m_hasData
        && lhs.m_propertyOverrideFlags == rhs.m_propertyOverrideFlags
        && lhs.m_mergeFlags == rhs.m_mergeFlags
        && lhs.m_backgroundColor == rhs.m_backgroundColor
        && retainedTableStyleColorEqual(lhs.m_backgroundColorCmc,
                                        rhs.m_backgroundColorCmc)
        && lhs.m_contentLayout == rhs.m_contentLayout
        && retainedTableStyleContentEqual(lhs.m_contentFormat,
                                          rhs.m_contentFormat)
        && lhs.m_marginOverrideFlags == rhs.m_marginOverrideFlags
        && retainedDoubleEqual(lhs.m_verticalMargin, rhs.m_verticalMargin)
        && retainedDoubleEqual(lhs.m_horizontalMargin,
                               rhs.m_horizontalMargin)
        && retainedDoubleEqual(lhs.m_bottomMargin, rhs.m_bottomMargin)
        && retainedDoubleEqual(lhs.m_rightMargin, rhs.m_rightMargin)
        && retainedDoubleEqual(lhs.m_marginHorizontalSpacing,
                               rhs.m_marginHorizontalSpacing)
        && retainedDoubleEqual(lhs.m_marginVerticalSpacing,
                               rhs.m_marginVerticalSpacing)
        && lhs.m_id == rhs.m_id
        && (!compareStyleClass || lhs.m_styleClass == rhs.m_styleClass)
        && (!compareName || lhs.m_name == rhs.m_name)
        && retainedTableStyleBordersEqual(lhs.m_borders, rhs.m_borders);
}

bool retainedPendingHandleRefsEqual(
        const std::vector<DRW_TableEntry::PendingHandleRef>& lhs,
        const std::vector<DRW_TableEntry::PendingHandleRef>& rhs) noexcept {
    if (lhs.size() != rhs.size())
        return false;
    for (std::size_t index = 0; index < lhs.size(); ++index) {
        const DRW_TableEntry::PendingHandleRef& left = lhs[index];
        const DRW_TableEntry::PendingHandleRef& right = rhs[index];
        if (left.indexInExtData != right.indexInExtData
            || left.handleRef != right.handleRef
            || left.rawHandleRef != right.rawHandleRef
            || left.useRawHandleRef != right.useRawHandleRef)
            return false;
    }
    return true;
}

bool retainedCellStyleMapsEqual(const DRW_CellStyleMap& lhs,
                                const DRW_CellStyleMap& rhs,
                                bool compareCellStyleNames = true,
                                bool compareCellStyleClasses = true) noexcept {
    if (lhs.tType != rhs.tType || lhs.handle != rhs.handle
        || lhs.parentHandle != rhs.parentHandle || lhs.name != rhs.name
        || lhs.flags != rhs.flags || lhs.xDictHandle != rhs.xDictHandle
        || lhs.reactorHandles != rhs.reactorHandles
        || lhs.reactorCount() != rhs.reactorCount()
        || lhs.extensionDictionaryFlag() != rhs.extensionDictionaryFlag()
        || lhs.hasDataStorageBinaryData() != rhs.hasDataStorageBinaryData()
        || lhs.hasDwgCommonLinkTail() != rhs.hasDwgCommonLinkTail()
        || !retainedPendingHandleRefsEqual(lhs.pendingAppIdResolutions,
                                           rhs.pendingAppIdResolutions)
        || !retainedPendingHandleRefsEqual(lhs.pendingLayerRefResolutions,
                                           rhs.pendingLayerRefResolutions)
        || !retainedVariantListsEqual(lhs.appData, rhs.appData)
        || lhs.extData.size() != rhs.extData.size()
        || lhs.m_cellStyles.size() != rhs.m_cellStyles.size()
        || lhs.m_subrecordRanges.size() != rhs.m_subrecordRanges.size())
        return false;
    for (std::size_t index = 0; index < lhs.extData.size(); ++index) {
        const DRW_Variant* left = lhs.extData[index];
        const DRW_Variant* right = rhs.extData[index];
        if ((left == nullptr) != (right == nullptr)
            || (left != nullptr && !retainedVariantEqual(*left, *right)))
            return false;
    }
    for (std::size_t index = 0; index < lhs.m_cellStyles.size(); ++index) {
        if (!retainedCellStyleEqual(lhs.m_cellStyles[index],
                                    rhs.m_cellStyles[index],
                                    compareCellStyleNames,
                                    compareCellStyleClasses))
            return false;
    }
    for (std::size_t index = 0; index < lhs.m_subrecordRanges.size();
         ++index) {
        const DRW_DwgSubrecordRange& left = lhs.m_subrecordRanges[index];
        const DRW_DwgSubrecordRange& right = rhs.m_subrecordRanges[index];
        if (left.m_name != right.m_name
            || left.m_startBit != right.m_startBit
            || left.m_bitSize != right.m_bitSize
            || left.m_version != right.m_version
            || left.m_count != right.m_count
            || left.m_parseComplete != right.m_parseComplete)
            return false;
    }
    return true;
}

bool collectCellStyleOverrides(
        const DRW_RawDxfObject& raw,
        const DRW_CellStyleMap& original,
        const DRW_CellStyleMap& edited,
        std::vector<std::pair<std::size_t, std::string>>& nameOverrides,
        std::vector<std::pair<std::size_t, std::int32_t>>& classOverrides) {
    if (original.m_cellStyles.size() != edited.m_cellStyles.size())
        return false;
    const auto isString = [](const DRW_Variant& group, int code,
                             std::string_view expected) {
        return group.code() == code
            && group.type() == DRW_Variant::STRING
            && group.c_str() != nullptr
            && std::string_view(group.c_str()) == expected;
    };
    const auto isInteger = [](const DRW_Variant& group, int code,
                              std::int32_t expected) {
        if (group.code() != code)
            return false;
        if (group.type() == DRW_Variant::INTEGER)
            return group.i_val() == expected;
        if (group.type() == DRW_Variant::INTEGER64)
            return group.i64_val() == expected;
        return false;
    };

    std::size_t styleIndex = 0u;
    std::size_t overrideTextBytes = 0u;
    for (std::size_t index = 0; index < raw.groups.size(); ++index) {
        if (!isString(raw.groups[index], 1, "CELLSTYLE_BEGIN"))
            continue;
        if (styleIndex >= original.m_cellStyles.size()
            || raw.groups.size() - index < 5u)
            return false;
        const DRW_TableStyleCellStyle& before =
            original.m_cellStyles[styleIndex];
        const DRW_TableStyleCellStyle& after =
            edited.m_cellStyles[styleIndex];
        if (!isInteger(raw.groups[index + 1u], 90, before.m_id)
            || !isInteger(raw.groups[index + 2u], 91, before.m_styleClass)
            || raw.groups[index + 3u].code() != 300
            || raw.groups[index + 3u].type() != DRW_Variant::STRING
            || raw.groups[index + 3u].c_str() == nullptr
            || std::string_view(raw.groups[index + 3u].c_str())
                != before.m_name
            || !isString(raw.groups[index + 4u], 309, "CELLSTYLE_END"))
            return false;
        if (after.m_styleClass < 0 || after.m_styleClass > 2)
            return false;
        if (after.m_styleClass != before.m_styleClass) {
            if (raw.groups[index + 2u].type() != DRW_Variant::INTEGER)
                return false;
            classOverrides.emplace_back(index + 2u, after.m_styleClass);
        }
        if (after.m_name != before.m_name) {
            if (after.m_name.size() > 1024u * 1024u
                || after.m_name.find('\0') != std::string::npos
                || after.m_name.find('\r') != std::string::npos
                || after.m_name.find('\n') != std::string::npos
                || !DRW_TextCodec::isUtf8ScalarText(after.m_name))
                return false;
            const std::size_t retainedTextBytes = after.m_name.size() + 1u;
            if (retainedTextBytes
                > kMaxAdapterCellStyleMapRetainedBytes - overrideTextBytes)
                return false;
            nameOverrides.emplace_back(index + 3u, after.m_name);
            overrideTextBytes += retainedTextBytes;
        }
        ++styleIndex;
        index += 4u;
    }
    return styleIndex == original.m_cellStyles.size();
}

bool retainedRawDxfObjectsEqual(const DRW_RawDxfObject& lhs,
                                const DRW_RawDxfObject& rhs) noexcept {
    if (lhs.name != rhs.name || lhs.handle != rhs.handle
        || lhs.parentHandle != rhs.parentHandle || lhs.hasRawValues != rhs.hasRawValues
        || lhs.m_version != rhs.m_version || lhs.groups.size() != rhs.groups.size()
        || lhs.rawValues != rhs.rawValues)
        return false;
    for (std::size_t index = 0; index < lhs.groups.size(); ++index) {
        if (!retainedVariantEqual(lhs.groups[index], rhs.groups[index]))
            return false;
    }
    return true;
}

std::string layoutSymbolKey(std::string value);
// Shared source/live reciprocal association algorithm. Inputs are typed views,
// not reparsed payloads or an editable-container copy. Other graph/space/UCS/
// viewport/name/consumer gates remain with each caller.
template<class Layouts,class Records>
bool reciprocalLayoutAssociations(const Layouts& layouts,const Records& records,std::string& failure) {
    std::set<std::uint32_t> associated;
    for(const auto& item:layouts) {
        const auto& layout=*item.second;const auto handle=layout.paperSpaceBlockRecordHandle.ref;
        const auto record=records.find(handle);
        if(!handle||record==records.end()) {failure="LAYOUT associated BLOCK_RECORD is null or missing";return false;}
        if(record->second->layoutHandle!=layout.handle) {failure="LAYOUT and BLOCK_RECORD backlinks disagree";return false;}
        if(!associated.insert(handle).second) {failure="multiple LAYOUT records share one BLOCK_RECORD";return false;}
    }
    for(const auto& item:records)if(item.second->layoutHandle) {
        const auto layout=layouts.find(item.second->layoutHandle);
        if(layout==layouts.end()||layout->second->paperSpaceBlockRecordHandle.ref!=item.first) {
            failure="BLOCK_RECORD has a missing or nonreciprocal LAYOUT target";return false;
        }
    }
    return true;
}
