bool addAssociativeRetainedBytes(
        std::size_t amount, std::size_t& total) noexcept {
    if (amount > kMaxAssociativeDxfRetainedBytes - total)
        return false;
    total += amount;
    return true;
}

bool addAssociativeSlotBytes(
        std::size_t count, std::size_t slotSize,
        std::size_t& total) noexcept {
    if (slotSize != 0u
        && count > kMaxAssociativeDxfRetainedBytes / slotSize)
        return false;
    return addAssociativeRetainedBytes(count * slotSize, total);
}

bool estimateAssociativeVariantBytes(
        const DRW_Variant* value, std::size_t& total) noexcept {
    if (value == nullptr)
        return true;
    if (!addAssociativeRetainedBytes(sizeof(DRW_Variant), total))
        return false;
    std::size_t payload = 0u;
    return value->estimateRetainedPayloadBytes(kMaxAssociativeDxfRetainedBytes, payload)
        && addAssociativeRetainedBytes(payload, total);
}

bool estimateTableEntryVariantBytes(
        const DRW_Variant* value, std::size_t& total) noexcept {
    return estimateAssociativeVariantBytes(value, total);
}

bool addTableEntryRetainedBytes(
        const DRW_TableEntry& entry, std::size_t& estimate) noexcept {
    if (!addAssociativeRetainedBytes(entry.name.size() + 1u, estimate)
        || !addAssociativeSlotBytes(entry.reactorHandles.size(),
                                    sizeof(std::uint32_t), estimate)
        || !addAssociativeSlotBytes(entry.pendingAppIdResolutions.size(),
                sizeof(DRW_TableEntry::PendingHandleRef), estimate)
        || !addAssociativeSlotBytes(entry.pendingLayerRefResolutions.size(),
                sizeof(DRW_TableEntry::PendingHandleRef), estimate)
        || !addAssociativeSlotBytes(entry.extData.size(),
                                    sizeof(DRW_Variant*), estimate)
        || !addAssociativeSlotBytes(entry.appData.size(),
                sizeof(std::list<DRW_Variant>), estimate))
        return false;
    for (const DRW_Variant* value : entry.extData) {
        if (!estimateTableEntryVariantBytes(value, estimate))
            return false;
    }
    for (const auto& appGroup : entry.appData) {
        for (const DRW_Variant& value : appGroup) {
            if (!estimateTableEntryVariantBytes(&value, estimate))
                return false;
        }
    }
    return true;
}

bool addImageDefinitionRetainedBytes(
        const DRW_ImageDef& definition, std::size_t& estimate) noexcept {
    using ImageDefinitionMapValue =
        std::pair<const dx_data::ImageDefinitionKey, DRW_ImageDef>;
    using ReactorMapValue = std::pair<const std::string, std::string>;
    estimate = sizeof(ImageDefinitionMapValue) + 3u * sizeof(void*);
    if (!addTableEntryRetainedBytes(
            static_cast<const DRW_TableEntry&>(definition), estimate)
        || !addAssociativeRetainedBytes(definition.name.size() + 1u, estimate)
        || !addAssociativeSlotBytes(definition.reactors.size(),
                sizeof(ReactorMapValue) + 3u * sizeof(void*), estimate))
        return false;
    for (const auto& reactor : definition.reactors) {
        if (!addAssociativeRetainedBytes(reactor.first.size() + 1u, estimate)
            || !addAssociativeRetainedBytes(reactor.second.size() + 1u,
                                            estimate))
            return false;
    }
    return estimate <= kMaxAdapterImageDefinitionRetainedBytes;
}

bool addStringPayloadBytes(
        const UTF8STRING& value, std::size_t& total) noexcept {
    return addAssociativeRetainedBytes(value.size() + 1u, total);
}

template <typename T>
bool addVectorPayloadBytes(
        const std::vector<T>& values, std::size_t& total) noexcept {
    return addAssociativeSlotBytes(values.size(), sizeof(T), total);
}

bool addStringVectorPayloadBytes(
        const std::vector<UTF8STRING>& values,
        std::size_t& total) noexcept {
    if (!addVectorPayloadBytes(values, total))
        return false;
    for (const UTF8STRING& value : values) {
        if (!addStringPayloadBytes(value, total))
            return false;
    }
    return true;
}

template <typename T>
bool addNestedVectorPayloadBytes(
        const std::vector<std::vector<T>>& values,
        std::size_t& total) noexcept {
    if (!addAssociativeSlotBytes(values.size(), sizeof(std::vector<T>), total))
        return false;
    for (const std::vector<T>& inner : values) {
        if (!addVectorPayloadBytes(inner, total))
            return false;
    }
    return true;
}

bool addNestedStringVectorPayloadBytes(
        const std::vector<std::vector<UTF8STRING>>& values,
        std::size_t& total) noexcept {
    if (!addAssociativeSlotBytes(
            values.size(), sizeof(std::vector<UTF8STRING>), total))
        return false;
    for (const std::vector<UTF8STRING>& inner : values) {
        if (!addStringVectorPayloadBytes(inner, total))
            return false;
    }
    return true;
}

bool addEntityCommonRetainedBytes(
        const DRW_Entity& entity, std::size_t& estimate) noexcept {
    if (!addStringPayloadBytes(entity.layer, estimate)
        || !addStringPayloadBytes(entity.lineType, estimate)
        || !addStringPayloadBytes(entity.proxyGraphics, estimate)
        || !addStringPayloadBytes(entity.colorName, estimate)
        || !addStringPayloadBytes(entity.dataStorageHandleKey, estimate)
        || !addStringPayloadBytes(
                entity.dataStoragePayloadMarkerSection, estimate)
        || !addStringPayloadBytes(
                entity.proxyGraphicsProvenance().sourceCodePage, estimate)
        || !addVectorPayloadBytes(entity.reactorHandles, estimate)
        || !addVectorPayloadBytes(entity.pendingAppIdResolutions, estimate)
        || !addVectorPayloadBytes(entity.pendingLayerRefResolutions, estimate)
        || !addVectorPayloadBytes(entity.dataStorageData, estimate)
        || !addVectorPayloadBytes(entity.extData, estimate))
        return false;

    for (const auto& value : entity.extData) {
        if (!estimateTableEntryVariantBytes(value.get(), estimate))
            return false;
    }

    if (!addAssociativeSlotBytes(entity.appData.size(),
            sizeof(std::list<DRW_Variant>) + 2u * sizeof(void*), estimate))
        return false;
    for (const auto& group : entity.appData) {
        if (!addAssociativeSlotBytes(group.size(),
                sizeof(DRW_Variant) + 2u * sizeof(void*), estimate))
            return false;
        for (const DRW_Variant& value : group) {
            if (!estimateTableEntryVariantBytes(&value, estimate))
                return false;
        }
    }
    return estimate <= kMaxAdapterTypedEntityRetainedBytes;
}

bool addAcisWireframeRetainedBytes(
        const DRW_AcisBrep& brep, std::size_t& estimate) noexcept {
    if (!addVectorPayloadBytes(brep.vertices, estimate)
        || !addVectorPayloadBytes(brep.edges, estimate)
        || !addVectorPayloadBytes(brep.faces, estimate)
        || !addStringVectorPayloadBytes(brep.diagnostics, estimate))
        return false;
    for (const DRW_AcisEdge& edge : brep.edges) {
        if (!addVectorPayloadBytes(edge.controlPoints, estimate))
            return false;
    }
    for (const DRW_AcisFace& face : brep.faces) {
        if (!addVectorPayloadBytes(face.loops, estimate))
            return false;
    }
    return true;
}

bool addModelerGeometryRetainedBytes(
        const DRW_ModelerGeometry& modeler,
        std::size_t& estimate) noexcept {
    if (!addStringPayloadBytes(modeler.m_dxfModelerUid, estimate)
        || !addVectorPayloadBytes(modeler.m_rawBytes, estimate)
        || !addVectorPayloadBytes(modeler.m_dwgAcisPayload, estimate)
        || !addVectorPayloadBytes(modeler.m_dxfPayloadChunks, estimate)
        || !addVectorPayloadBytes(modeler.m_payloadRanges, estimate)
        || !addAcisWireframeRetainedBytes(modeler.m_wireframe, estimate))
        return false;
    for (const DRW_ModelerPayloadRange& range : modeler.m_payloadRanges) {
        if (!addStringPayloadBytes(range.m_markerText, estimate))
            return false;
    }
    return estimate <= kMaxAdapterTypedEntityRetainedBytes;
}

bool addSurfaceRetainedBytes(
        const DRW_Surface& surface, std::size_t& estimate) noexcept {
    if (!addVectorPayloadBytes(surface.rawAcisData, estimate)
        || !addVectorPayloadBytes(surface.dxfPayloadChunks, estimate)
        || !addVectorPayloadBytes(surface.crossSectionHandles, estimate)
        || !addVectorPayloadBytes(surface.guideCurveHandles, estimate)
        || !addAcisWireframeRetainedBytes(surface.m_wireframe, estimate))
        return false;
    if (const auto* extruded =
            dynamic_cast<const DRW_ExtrudedSurface*>(&surface)) {
        if (!addVectorPayloadBytes(extruded->dxfBinaryData, estimate))
            return false;
    } else if (const auto* revolved =
            dynamic_cast<const DRW_RevolvedSurface*>(&surface)) {
        if (!addVectorPayloadBytes(revolved->dxfBinaryData, estimate))
            return false;
    } else if (const auto* swept =
            dynamic_cast<const DRW_SweptSurface*>(&surface)) {
        if (!addVectorPayloadBytes(swept->sweepData, estimate)
            || !addVectorPayloadBytes(swept->pathData, estimate))
            return false;
    } else if (const auto* lofted =
            dynamic_cast<const DRW_LoftedSurface*>(&surface)) {
        if (!addVectorPayloadBytes(lofted->dxfReferenceData, estimate))
            return false;
        for (const DRW_Variant& value : lofted->dxfReferenceData) {
            if (!estimateTableEntryVariantBytes(&value, estimate))
                return false;
        }
    }
    return estimate <= kMaxAdapterTypedEntityRetainedBytes;
}

bool addMeshRetainedBytes(
        const DRW_Mesh& mesh, std::size_t& estimate) noexcept {
    if (!addVectorPayloadBytes(mesh.subdivVertices, estimate)
        || !addVectorPayloadBytes(mesh.vertices, estimate)
        || !addNestedVectorPayloadBytes(mesh.faces, estimate)
        || !addVectorPayloadBytes(mesh.edges, estimate)
        || !addVectorPayloadBytes(mesh.creases, estimate)
        || !addVectorPayloadBytes(mesh.propertyOverrides, estimate))
        return false;
    for (const DRW_MeshPropertyOverride& overrideValue :
            mesh.propertyOverrides) {
        if (!addVectorPayloadBytes(
                overrideValue.propertyTypes, estimate))
            return false;
    }
    return estimate <= kMaxAdapterTypedEntityRetainedBytes;
}

bool addImageRetainedBytes(
        const DRW_Image& image, std::size_t& estimate) noexcept {
    return addVectorPayloadBytes(image.clipPath, estimate)
        && estimate <= kMaxAdapterTypedEntityRetainedBytes;
}

bool addViewportRetainedBytes(
        const DRW_Viewport& viewport, std::size_t& estimate) noexcept {
    return addStringPayloadBytes(viewport.styleSheet, estimate)
        && addStringPayloadBytes(viewport.ambientColorName, estimate)
        && addVectorPayloadBytes(viewport.frozenLayerHandles, estimate)
        && estimate <= kMaxAdapterTypedEntityRetainedBytes;
}

bool addSplineRetainedBytes(
        const DRW_Spline& spline, std::size_t& estimate) noexcept {
    if (!addVectorPayloadBytes(spline.knotslist, estimate)
        || !addVectorPayloadBytes(spline.weightlist, estimate)
        || !addVectorPayloadBytes(spline.controllist, estimate)
        || !addVectorPayloadBytes(spline.fitlist, estimate))
        return false;
    for (const auto& point : spline.controllist) {
        if (point != nullptr
            && !addAssociativeRetainedBytes(sizeof(DRW_Coord), estimate))
            return false;
    }
    for (const auto& point : spline.fitlist) {
        if (point != nullptr
            && !addAssociativeRetainedBytes(sizeof(DRW_Coord), estimate))
            return false;
    }
    return estimate <= kMaxAdapterTypedEntityRetainedBytes;
}

bool addLWPolylineRetainedBytes(
        const DRW_LWPolyline& polyline, std::size_t& estimate) noexcept {
    if (!addVectorPayloadBytes(polyline.vertlist, estimate))
        return false;
    for (const auto& vertex : polyline.vertlist) {
        if (vertex != nullptr
            && !addAssociativeRetainedBytes(sizeof(DRW_Vertex2D), estimate))
            return false;
    }
    return estimate <= kMaxAdapterTypedEntityRetainedBytes;
}

bool addPolylineRetainedBytes(
        const DRW_Polyline& polyline, std::size_t& estimate) noexcept {
    if (!addVectorPayloadBytes(polyline.vertlist, estimate)
        || !addAssociativeSlotBytes(polyline.dwgHandleListSize(),
                sizeof(std::uint32_t) + 2u * sizeof(void*), estimate))
        return false;
    for (const auto& vertex : polyline.vertlist) {
        if (vertex == nullptr)
            continue;
        if (!addAssociativeRetainedBytes(sizeof(DRW_Vertex), estimate)
            || !addEntityCommonRetainedBytes(*vertex, estimate))
            return false;
    }
    if (polyline.seqEndEntity != nullptr) {
        if (!addAssociativeRetainedBytes(sizeof(DRW_SeqEnd), estimate)
            || !addEntityCommonRetainedBytes(
                    *polyline.seqEndEntity, estimate))
            return false;
    }
    return estimate <= kMaxAdapterTypedEntityRetainedBytes;
}

bool addMLineRetainedBytes(
        const DRW_MLine& mline, std::size_t& estimate) noexcept {
    if (!addStringPayloadBytes(mline.styleName, estimate)
        || !addVectorPayloadBytes(mline.vertlist, estimate))
        return false;
    for (const DRW_MLineVertex& vertex : mline.vertlist) {
        if (!addNestedVectorPayloadBytes(vertex.segParms, estimate)
            || !addNestedVectorPayloadBytes(
                    vertex.areaFillParms, estimate))
            return false;
    }
    return estimate <= kMaxAdapterTypedEntityRetainedBytes;
}

bool addHatchBoundaryEntityRetainedBytes(
        const DRW_Entity& entity, std::size_t& estimate) noexcept {
    if (const auto* spline = dynamic_cast<const DRW_Spline*>(&entity)) {
        return addAssociativeRetainedBytes(sizeof(DRW_Spline), estimate)
            && addEntityCommonRetainedBytes(*spline, estimate)
            && addSplineRetainedBytes(*spline, estimate);
    }
    if (const auto* polyline =
            dynamic_cast<const DRW_LWPolyline*>(&entity)) {
        return addAssociativeRetainedBytes(sizeof(DRW_LWPolyline), estimate)
            && addEntityCommonRetainedBytes(*polyline, estimate)
            && addLWPolylineRetainedBytes(*polyline, estimate);
    }
    if (const auto* arc = dynamic_cast<const DRW_Arc*>(&entity)) {
        return addAssociativeRetainedBytes(sizeof(DRW_Arc), estimate)
            && addEntityCommonRetainedBytes(*arc, estimate);
    }
    if (const auto* ellipse = dynamic_cast<const DRW_Ellipse*>(&entity)) {
        return addAssociativeRetainedBytes(sizeof(DRW_Ellipse), estimate)
            && addEntityCommonRetainedBytes(*ellipse, estimate);
    }
    if (const auto* line = dynamic_cast<const DRW_Line*>(&entity)) {
        return addAssociativeRetainedBytes(sizeof(DRW_Line), estimate)
            && addEntityCommonRetainedBytes(*line, estimate);
    }
    return false;
}

bool addHatchRetainedBytes(
        const DRW_Hatch& hatch, std::size_t& estimate) noexcept {
    if (!addStringPayloadBytes(hatch.name, estimate)
        || !addStringPayloadBytes(hatch.gradName, estimate)
        || !addVectorPayloadBytes(hatch.patternLines, estimate)
        || !addVectorPayloadBytes(hatch.looplist, estimate)
        || !addVectorPayloadBytes(hatch.gradColors, estimate)
        || !addVectorPayloadBytes(hatch.seedPoints, estimate))
        return false;
    for (const DRW_Hatch::PatternLine& line : hatch.patternLines) {
        if (!addVectorPayloadBytes(line.dashList, estimate))
            return false;
    }
    for (const DRW_Hatch::GradientStop& stop : hatch.gradColors) {
        if (!addStringPayloadBytes(stop.colorName, estimate)
            || !addStringPayloadBytes(stop.colorBookName, estimate))
            return false;
    }
    for (const auto& loop : hatch.looplist) {
        if (loop == nullptr)
            continue;
        if (!addAssociativeRetainedBytes(sizeof(DRW_HatchLoop), estimate)
            || !addVectorPayloadBytes(loop->objlist, estimate)
            || !addVectorPayloadBytes(loop->m_boundaryHandles, estimate))
            return false;
        for (const auto& entity : loop->objlist) {
            if (entity == nullptr
                || !addHatchBoundaryEntityRetainedBytes(*entity, estimate))
                return false;
        }
    }
    return estimate <= kMaxAdapterTypedEntityRetainedBytes;
}

bool addMPolygonRetainedBytes(
        const DRW_MPolygon& polygon, std::size_t& estimate) noexcept {
    return addStringPayloadBytes(polygon.fillColorName, estimate)
        && addStringPayloadBytes(polygon.fillColorBookName, estimate)
        && estimate <= kMaxAdapterTypedEntityRetainedBytes;
}

bool addMTextRetainedBytes(
        const DRW_MText& mtext, std::size_t& estimate) noexcept {
    return addStringPayloadBytes(mtext.m_backgroundColorName, estimate)
        && addVectorPayloadBytes(mtext.m_r2018ColumnHeights, estimate)
        && addVectorPayloadBytes(mtext.m_r2018AnnotativeData, estimate)
        && estimate <= kMaxAdapterTypedEntityRetainedBytes;
}

bool addArcAlignedTextRetainedBytes(
        const DRW_ArcAlignedText& text, std::size_t& estimate) noexcept {
    return addStringPayloadBytes(text.m_textSize, estimate)
        && addStringPayloadBytes(text.m_xScale, estimate)
        && addStringPayloadBytes(text.m_charSpacing, estimate)
        && addStringPayloadBytes(text.m_offsetFromArc, estimate)
        && addStringPayloadBytes(text.m_rightOffset, estimate)
        && addStringPayloadBytes(text.m_leftOffset, estimate)
        && addStringPayloadBytes(text.m_fontName, estimate)
        && addStringPayloadBytes(text.m_bigFontName, estimate)
        && estimate <= kMaxAdapterTypedEntityRetainedBytes;
}

bool addTextRetainedBytes(
        const DRW_Text& text, std::size_t& estimate) noexcept {
    if (!addStringPayloadBytes(text.text, estimate)
        || !addStringPayloadBytes(text.style, estimate))
        return false;
    if (const auto* mtext = dynamic_cast<const DRW_MText*>(&text)) {
        if (!addMTextRetainedBytes(*mtext, estimate))
            return false;
    }
    if (const auto* arcText =
            dynamic_cast<const DRW_ArcAlignedText*>(&text)) {
        if (!addArcAlignedTextRetainedBytes(*arcText, estimate))
            return false;
    }
    return estimate <= kMaxAdapterTypedEntityRetainedBytes;
}

bool addToleranceRetainedBytes(
        const DRW_Tolerance& tolerance, std::size_t& estimate) noexcept {
    return addStringPayloadBytes(tolerance.text, estimate)
        && addStringPayloadBytes(tolerance.dimStyleName, estimate)
        && estimate <= kMaxAdapterTypedEntityRetainedBytes;
}

bool addAttributeRetainedBytes(
        const DRW_Attrib& attribute, std::size_t& estimate) noexcept {
    if (!addStringPayloadBytes(attribute.tag, estimate)
        || !addStringPayloadBytes(attribute.m_r2018OuterAnnotativeAppIdName,
                                  estimate)
        || !addVectorPayloadBytes(
                attribute.m_r2018OuterAnnotativeData, estimate)
        || !addTextRetainedBytes(attribute, estimate))
        return false;
    if (attribute.mtext != nullptr) {
        if (!addAssociativeRetainedBytes(
                sizeof(DRW_MText), estimate)
            // Nested MTEXT owns the same common strings, variants and
            // metadata vectors as a standalone entity. Its copy retains all
            // of them, not only the text/column/background-specific payload.
            || !addEntityCommonRetainedBytes(*attribute.mtext, estimate)
            || !addMTextRetainedBytes(*attribute.mtext, estimate)
            || !addStringPayloadBytes(
                    attribute.mtext->text, estimate)
            || !addStringPayloadBytes(
                    attribute.mtext->style, estimate))
            return false;
    }
    return estimate <= kMaxAdapterTypedEntityRetainedBytes;
}

bool addInsertRetainedBytes(
        const DRW_Insert& insert, std::size_t& estimate) noexcept {
    if (!addStringPayloadBytes(insert.name, estimate)
        || !addVectorPayloadBytes(insert.attribHandles, estimate)
        || !addVectorPayloadBytes(insert.attlist, estimate))
        return false;
    for (const auto& attribute : insert.attlist) {
        if (attribute == nullptr)
            continue;
        if (!addAssociativeRetainedBytes(sizeof(DRW_Attrib), estimate)
            || !addEntityCommonRetainedBytes(*attribute, estimate)
            || !addAttributeRetainedBytes(*attribute, estimate))
            return false;
    }
    if (insert.seqEndEntity != nullptr) {
        if (!addAssociativeRetainedBytes(sizeof(DRW_SeqEnd), estimate)
            || !addEntityCommonRetainedBytes(*insert.seqEndEntity, estimate))
            return false;
    }
    return estimate <= kMaxAdapterTypedEntityRetainedBytes;
}

bool addCadValueRetainedBytes(
        const DRW_CadValue& value, std::size_t& estimate) noexcept {
    return estimateTableEntryVariantBytes(&value.m_value, estimate)
        && addStringPayloadBytes(value.m_formatString, estimate)
        && addStringPayloadBytes(value.m_valueString, estimate)
        && addVectorPayloadBytes(value.m_rawData, estimate);
}

bool addTableContentRetainedBytes(
        const DRW_TableContent& content, std::size_t& estimate) noexcept {
    if (!addStringPayloadBytes(content.m_name, estimate)
        || !addStringPayloadBytes(content.m_description, estimate)
        || !addVectorPayloadBytes(content.m_columns, estimate)
        || !addVectorPayloadBytes(content.m_rows, estimate)
        || !addVectorPayloadBytes(content.m_fieldHandles, estimate)
        || !addVectorPayloadBytes(content.m_mergedRanges, estimate)
        || !addVectorPayloadBytes(content.m_subrecordRanges, estimate))
        return false;
    for (const auto& range : content.m_subrecordRanges)
        if (!addStringPayloadBytes(range.m_name, estimate)) return false;
    for (const DRW_TableColumn& column : content.m_columns) {
        if (!addStringPayloadBytes(column.m_name, estimate))
            return false;
    }
    for (const DRW_TableRow& row : content.m_rows) {
        if (!addVectorPayloadBytes(row.m_cells, estimate))
            return false;
        for (const DRW_TableCell& cell : row.m_cells) {
            if (!addStringPayloadBytes(cell.m_toolTip, estimate)
                || !addStringPayloadBytes(cell.m_textStyleName, estimate)
                || !addVectorPayloadBytes(cell.m_attributes, estimate)
                || !addVectorPayloadBytes(cell.m_contents, estimate))
                return false;
            for (const DRW_TableCellAttribute& attribute :
                    cell.m_attributes) {
                if (!addStringPayloadBytes(attribute.m_text, estimate))
                    return false;
            }
            for (const DRW_TableCellContent& cellContent : cell.m_contents) {
                if (!addStringPayloadBytes(cellContent.m_text, estimate)
                    || !addCadValueRetainedBytes(
                            cellContent.m_value, estimate))
                    return false;
            }
        }
    }
    return estimate <= kMaxAdapterTypedEntityRetainedBytes;
}

bool addTableRetainedBytes(
        const DRW_Table& table, std::size_t& estimate) noexcept {
    return addTableContentRetainedBytes(table.m_content, estimate);
}

bool addTableSourceColorBytes(
        const DRW_TableStyleCmcColor& color, std::size_t& bytes) noexcept {
    return addStringPayloadBytes(color.m_name, bytes)
        && addStringPayloadBytes(color.m_bookName, bytes);
}

bool addTableSourceFormatBytes(
        const DRW_TableStyleContentFormat& format, std::size_t& bytes) noexcept {
    return addStringPayloadBytes(format.m_valueFormatString, bytes)
        && addTableSourceColorBytes(format.m_contentColorCmc, bytes);
}

bool addTableSourceStyleBytes(
        const DRW_TableStyleCellStyle& style, std::size_t& bytes) noexcept {
    if (!addStringPayloadBytes(style.m_name, bytes)
        || !addTableSourceColorBytes(style.m_backgroundColorCmc, bytes)
        || !addTableSourceFormatBytes(style.m_contentFormat, bytes)
        || !addVectorPayloadBytes(style.m_borders, bytes))
        return false;
    for (const auto& border : style.m_borders)
        if (!addTableSourceColorBytes(border.m_colorCmc, bytes)) return false;
    return true;
}

bool addTableSourceObjectNodeBytes(
        const DRW_TableEntry& object, std::size_t& bytes) noexcept {
    // The reusable object estimator charges the list headers and variants;
    // these source snapshots also charge both levels of list-node links.
    if (!addAssociativeSlotBytes(object.appData.size(), 2u * sizeof(void*), bytes)) return false;
    for (const auto& group : object.appData)
        if (!addAssociativeSlotBytes(group.size(), 2u * sizeof(void*), bytes)) return false;
    return true;
}

bool estimateTableContentSourceBytes(
        const DRW_TableContentObject& content, std::size_t& bytes) noexcept {
    bytes = sizeof(DRW_TableContentObject);
    if (!addTableEntryRetainedBytes(content, bytes)
        || !addTableSourceObjectNodeBytes(content, bytes)
        || !addTableContentRetainedBytes(content.m_content, bytes)) return false;
    if (!content.m_dxfMetadata) return true;
    const auto& metadata = *content.m_dxfMetadata;
    const auto scopeBytes = [&bytes](const DRW_TableContentDxfMetadata::Scope& scope) {
        if (!addVectorPayloadBytes(scope.m_customItems, bytes)
            || !addTableSourceStyleBytes(scope.m_style, bytes)) return false;
        for (const auto& item : scope.m_customItems)
            if (!addStringPayloadBytes(item.m_name, bytes)
                || !addCadValueRetainedBytes(item.m_value, bytes)) return false;
        return true;
    };
    // Charge the full shared companion per baseline, including its control
    // block/lease overhead. Sharing is never used to bypass adapter ceilings.
    if (!addAssociativeRetainedBytes(sizeof(DRW_TableContentDxfMetadata)
            + 8u * sizeof(void*), bytes)
        || !addVectorPayloadBytes(metadata.m_columns, bytes)
        || !addVectorPayloadBytes(metadata.m_rows, bytes)
        || !addTableSourceStyleBytes(metadata.m_tableStyle, bytes)) return false;
    for (const auto& column : metadata.m_columns)
        if (!scopeBytes(column)) return false;
    for (const auto& row : metadata.m_rows) {
        if (!scopeBytes(row.m_scope) || !addVectorPayloadBytes(row.m_cells, bytes)) return false;
        for (const auto& cell : row.m_cells) {
            if (!scopeBytes(cell.m_scope)
                || !addVectorPayloadBytes(cell.m_contentFormats, bytes)
                || !addVectorPayloadBytes(cell.m_geometry, bytes)) return false;
            for (const auto& format : cell.m_contentFormats) {
                if (format && (!addAssociativeRetainedBytes(
                        sizeof(DRW_TableStyleContentFormat) + 4u * sizeof(void*), bytes)
                    || !addTableSourceFormatBytes(*format, bytes))) return false;
            }
        }
    }
    return bytes <= kMaxAdapterTypedEntityRetainedBytes;
}

bool estimateTableGeometrySourceBytes(
        const DRW_TableGeometry& geometry, std::size_t& bytes) noexcept {
    bytes = sizeof(DRW_TableGeometry);
    if (!addTableEntryRetainedBytes(geometry, bytes)
        || !addTableSourceObjectNodeBytes(geometry, bytes)
        || !addVectorPayloadBytes(geometry.m_cells, bytes)) return false;
    for (const auto& cell : geometry.m_cells)
        if (!addVectorPayloadBytes(cell.m_contents, bytes)) return false;
    return bytes <= kMaxAdapterTypedEntityRetainedBytes;
}

bool addDimensionRetainedBytes(
        const DRW_Dimension& dimension, std::size_t& estimate) noexcept {
    return addAssociativeRetainedBytes(
               dimension.retainedStringPayloadBytes(), estimate)
        && estimate <= kMaxAdapterTypedEntityRetainedBytes;
}

bool addLeaderRetainedBytes(
        const DRW_Leader& leader, std::size_t& estimate) noexcept {
    if (!addStringPayloadBytes(leader.style, estimate)
        || !addVectorPayloadBytes(leader.vertexlist, estimate))
        return false;
    for (const auto& point : leader.vertexlist) {
        if (point != nullptr
            && !addAssociativeRetainedBytes(sizeof(DRW_Coord), estimate))
            return false;
    }
    return estimate <= kMaxAdapterTypedEntityRetainedBytes;
}

bool addMLeaderRetainedBytes(
        const DRW_MLeader& mleader, std::size_t& estimate) noexcept {
    const DRW_MLeaderAnnotContext& context = mleader.context;
    if (!addVectorPayloadBytes(mleader.arrowHeads, estimate)
        || !addVectorPayloadBytes(mleader.blockLabels, estimate)
        // DXF parsing keeps one retained-string accounting slot per label;
        // charge the bounded cardinality even for caller-built MLeaders.
        || !addAssociativeSlotBytes(mleader.blockLabels.size(),
                sizeof(std::size_t), estimate)
        || !addStringPayloadBytes(context.textLabel, estimate)
        || !addVectorPayloadBytes(context.columnSizes, estimate)
        || !addVectorPayloadBytes(context.roots, estimate))
        return false;
    for (const DRW_MLeader::BlockLabelEntry& label : mleader.blockLabels) {
        if (!addStringPayloadBytes(label.labelText, estimate))
            return false;
    }
    for (const DRW_MLeaderRoot& root : context.roots) {
        if (!addVectorPayloadBytes(root.breaks, estimate)
            || !addVectorPayloadBytes(root.leaderLines, estimate))
            return false;
        for (const DRW_MLeaderLeaderLine& line : root.leaderLines) {
            if (!addVectorPayloadBytes(line.points, estimate)
                || !addVectorPayloadBytes(line.breaks, estimate))
                return false;
        }
    }
    return estimate <= kMaxAdapterTypedEntityRetainedBytes;
}

bool estimateTypedEntityRetainedBytes(
        const DRW_Entity& entity, std::size_t inlineBytes,
        std::size_t& estimate) noexcept {
    estimate = inlineBytes;
    if (!addEntityCommonRetainedBytes(entity, estimate))
        return false;
    if (const auto* modeler =
            dynamic_cast<const DRW_ModelerGeometry*>(&entity)) {
        if (!addModelerGeometryRetainedBytes(*modeler, estimate))
            return false;
    }
    if (const auto* surface = dynamic_cast<const DRW_Surface*>(&entity)) {
        if (!addSurfaceRetainedBytes(*surface, estimate))
            return false;
    }
    if (const auto* mesh = dynamic_cast<const DRW_Mesh*>(&entity)) {
        if (!addMeshRetainedBytes(*mesh, estimate))
            return false;
    }
    if (const auto* image = dynamic_cast<const DRW_Image*>(&entity)) {
        if (!addImageRetainedBytes(*image, estimate))
            return false;
    }
    if (const auto* viewport =
            dynamic_cast<const DRW_Viewport*>(&entity)) {
        if (!addViewportRetainedBytes(*viewport, estimate))
            return false;
    }
    if (const auto* spline = dynamic_cast<const DRW_Spline*>(&entity)) {
        if (!addSplineRetainedBytes(*spline, estimate))
            return false;
    }
    if (const auto* lwPolyline =
            dynamic_cast<const DRW_LWPolyline*>(&entity)) {
        if (!addLWPolylineRetainedBytes(*lwPolyline, estimate))
            return false;
    }
    if (const auto* polyline = dynamic_cast<const DRW_Polyline*>(&entity)) {
        if (!addPolylineRetainedBytes(*polyline, estimate))
            return false;
    }
    if (const auto* mline = dynamic_cast<const DRW_MLine*>(&entity)) {
        if (!addMLineRetainedBytes(*mline, estimate))
            return false;
    }
    if (const auto* hatch = dynamic_cast<const DRW_Hatch*>(&entity)) {
        if (!addHatchRetainedBytes(*hatch, estimate))
            return false;
    }
    if (const auto* polygon = dynamic_cast<const DRW_MPolygon*>(&entity)) {
        if (!addMPolygonRetainedBytes(*polygon, estimate))
            return false;
    }
    if (const auto* text = dynamic_cast<const DRW_Text*>(&entity)) {
        if (!addTextRetainedBytes(*text, estimate))
            return false;
    }
    if (const auto* tolerance =
            dynamic_cast<const DRW_Tolerance*>(&entity)) {
        if (!addToleranceRetainedBytes(*tolerance, estimate))
            return false;
    }
    if (const auto* attribute = dynamic_cast<const DRW_Attrib*>(&entity)) {
        if (!addAttributeRetainedBytes(*attribute, estimate))
            return false;
    }
    if (const auto* attdef = dynamic_cast<const DRW_Attdef*>(&entity)) {
        if (!addStringPayloadBytes(attdef->prompt, estimate))
            return false;
    }
    if (const auto* insert = dynamic_cast<const DRW_Insert*>(&entity)) {
        if (!addInsertRetainedBytes(*insert, estimate))
            return false;
    }
    if (const auto* table = dynamic_cast<const DRW_Table*>(&entity)) {
        if (!addTableRetainedBytes(*table, estimate))
            return false;
    }
    if (const auto* dimension =
            dynamic_cast<const DRW_Dimension*>(&entity)) {
        if (!addDimensionRetainedBytes(*dimension, estimate))
            return false;
    }
    if (const auto* leader = dynamic_cast<const DRW_Leader*>(&entity)) {
        if (!addLeaderRetainedBytes(*leader, estimate))
            return false;
    }
    if (const auto* mleader = dynamic_cast<const DRW_MLeader*>(&entity)) {
        if (!addMLeaderRetainedBytes(*mleader, estimate))
            return false;
    }
    return estimate <= kMaxAdapterTypedEntityRetainedBytes;
}

