bool estimateLTypeTypedBytes(
        const DRW_LType& lineType, std::size_t& estimate,
        std::size_t& itemCount) noexcept {
    estimate = sizeof(DRW_LType);
    itemCount = 0u;
    const auto addItems = [&itemCount](std::size_t count) {
        if (itemCount > kMaxAdapterBasicTableItems
            || count > kMaxAdapterBasicTableItems - itemCount)
            return false;
        itemCount += count;
        return true;
    };
    if (!addTableEntryRetainedBytes(lineType, estimate)
        || !addStringPayloadBytes(lineType.desc, estimate)
        || !addVectorPayloadBytes(lineType.path, estimate)
        || !addItems(lineType.path.size())
        || !addVectorPayloadBytes(lineType.segments, estimate)
        || !addItems(lineType.segments.size())
        || !addVectorPayloadBytes(lineType.shapeHandles, estimate)
        || !addItems(lineType.shapeHandles.size())
        || !addAssociativeSlotBytes(lineType.synchronizedLengthCount(),
                sizeof(double), estimate)
        || !addItems(lineType.synchronizedLengthCount())
        || !addAssociativeSlotBytes(lineType.retainedSegmentTextCount(),
                sizeof(std::size_t), estimate)
        || !addItems(lineType.retainedSegmentTextCount()))
        return false;
    for (const DRW_LTypeSegment& segment : lineType.segments) {
        if (!addStringPayloadBytes(segment.text, estimate))
            return false;
    }
    return estimate <= kMaxAdapterBasicTableRetainedBytes;
}

