bool estimateDataStorageSectionBytes(
        const DRW_DataStorageSection& section,
        std::size_t& estimate) noexcept {
    estimate = sizeof(DRW_DataStorageSection);
    const auto addMapSlots = [&estimate](std::size_t count,
                                          std::size_t buckets,
                                          std::size_t valueSize) {
        return addAssociativeSlotBytes(
                   count, valueSize + 3u * sizeof(void*), estimate)
            && addAssociativeSlotBytes(buckets, sizeof(void*), estimate);
    };

    if (!addStringPayloadBytes(section.m_name, estimate)
        || !addVectorPayloadBytes(section.segments, estimate)
        || !addVectorPayloadBytes(section.dataIndexEntries, estimate)
        || !addVectorPayloadBytes(section.schemaIndexEntries, estimate)
        || !addVectorPayloadBytes(section.schemaPropertyEntries, estimate)
        || !addVectorPayloadBytes(section.schemaUnknownProperties, estimate)
        || !addVectorPayloadBytes(section.schemas, estimate)
        || !addStringVectorPayloadBytes(section.schemaPropertyNames, estimate)
        || !addVectorPayloadBytes(section.records, estimate)
        || !addVectorPayloadBytes(section.duplicateRecordHandleKeys, estimate)
        || !addVectorPayloadBytes(section.diagnostics, estimate))
        return false;

    for (const DRW_DataStorageSegment& segment : section.segments) {
        if (!addStringPayloadBytes(segment.name, estimate))
            return false;
    }
    for (const DRW_DataStorageSchema& schema : section.schemas) {
        if (!addVectorPayloadBytes(schema.indexes, estimate)
            || !addVectorPayloadBytes(schema.properties, estimate))
            return false;
        for (const DRW_DataStorageSchemaProperty& property : schema.properties) {
            if (!addStringPayloadBytes(property.name, estimate)
                || !addNestedVectorPayloadBytes(property.values, estimate))
                return false;
        }
    }
    for (const DRW_DataStorageRecord& record : section.records) {
        if (!addStringPayloadBytes(record.handleKey, estimate)
            || !addVectorPayloadBytes(record.blobPages, estimate)
            || !addVectorPayloadBytes(record.payload, estimate)
            || !addStringPayloadBytes(record.payloadMarkerSection, estimate))
            return false;
    }
    for (const DRW_DataStorageDiagnostic& diagnostic : section.diagnostics) {
        if (!addStringPayloadBytes(diagnostic.code, estimate)
            || !addStringPayloadBytes(diagnostic.message, estimate))
            return false;
    }

    if (!addMapSlots(section.recordIndexByHandle.size(),
                     section.recordIndexByHandle.bucket_count(),
                     sizeof(std::pair<const std::uint64_t, std::size_t>))
        || !addMapSlots(section.recordIndexByHandleKey.size(),
                        section.recordIndexByHandleKey.bucket_count(),
                        sizeof(std::pair<const UTF8STRING, std::size_t>))
        || !addMapSlots(section.recordIndexesByHandle.size(),
                        section.recordIndexesByHandle.bucket_count(),
                        sizeof(std::pair<const std::uint64_t,
                                         std::vector<std::size_t>>))
        || !addMapSlots(section.recordIndexesByHandleKey.size(),
                        section.recordIndexesByHandleKey.bucket_count(),
                        sizeof(std::pair<const UTF8STRING,
                                         std::vector<std::size_t>>)))
        return false;
    for (const auto& item : section.recordIndexByHandleKey) {
        if (!addStringPayloadBytes(item.first, estimate))
            return false;
    }
    for (const auto& item : section.recordIndexesByHandle) {
        if (!addVectorPayloadBytes(item.second, estimate))
            return false;
    }
    for (const auto& item : section.recordIndexesByHandleKey) {
        if (!addStringPayloadBytes(item.first, estimate)
            || !addVectorPayloadBytes(item.second, estimate))
            return false;
    }
    for (const UTF8STRING& key : section.duplicateRecordHandleKeys) {
        if (!addStringPayloadBytes(key, estimate))
            return false;
    }
    return estimate <= dx_iface::DataStorageCaptureMaxRetainedBytes;
}

