bool estimateDimStyleTypedBytes(
        const DRW_Dimstyle& dimStyle, std::size_t& estimate,
        std::size_t& itemCount) noexcept {
    estimate = sizeof(DRW_Dimstyle);
    itemCount = dimStyle.vars.size();
    if (itemCount > kMaxAdapterBasicTableItems
        || !addTableEntryRetainedBytes(dimStyle, estimate)
        || !addStringPayloadBytes(dimStyle.dimpost, estimate)
        || !addStringPayloadBytes(dimStyle.dimapost, estimate)
        || !addStringPayloadBytes(dimStyle.dimblk, estimate)
        || !addStringPayloadBytes(dimStyle.dimblk1, estimate)
        || !addStringPayloadBytes(dimStyle.dimblk2, estimate)
        || !addStringPayloadBytes(dimStyle.dimtxsty, estimate)
        || !addStringPayloadBytes(dimStyle.dimldrblk, estimate)
        || !addStringPayloadBytes(dimStyle.dimaltmzs, estimate)
        || !addStringPayloadBytes(dimStyle.dimmzs, estimate)
        || !addAssociativeSlotBytes(dimStyle.vars.size(),
                sizeof(std::pair<const std::string, DRW_Variant*>)
                    + 3u * sizeof(void*), estimate))
        return false;

    for (const auto& entry : dimStyle.vars) {
        if (!addStringPayloadBytes(entry.first, estimate)
            || !estimateTableEntryVariantBytes(entry.second, estimate))
            return false;
    }
    return estimate <= kMaxAdapterBasicTableRetainedBytes;
}

