template <typename Container, typename Value, typename Estimator>
void retainBasicTableTyped(dx_data* data, Container& destination,
        const Value& value, Estimator estimateValue) {
    constexpr std::size_t listNodeLinkBytes = 2u * sizeof(void*);
    if (data == nullptr || data->basicTableCaptureFailed)
        return;
    if (data->basicTableRetainedRecords >= kMaxAdapterBasicTableRecords) {
        data->basicTableCaptureFailed = true;
        return;
    }

    std::size_t estimatedBytes = 0u;
    std::size_t itemCount = 0u;
    if (!estimateValue(value, estimatedBytes, itemCount)
        || estimatedBytes > kMaxAdapterBasicTableRetainedBytes
            - listNodeLinkBytes
        || data->basicTableRetainedItems > kMaxAdapterBasicTableItems
        || itemCount > kMaxAdapterBasicTableItems
                            - data->basicTableRetainedItems
        || data->basicTableRetainedBytes
            > kMaxAdapterBasicTableRetainedBytes
        || estimatedBytes + listNodeLinkBytes
            > kMaxAdapterBasicTableRetainedBytes
                                - data->basicTableRetainedBytes) {
        data->basicTableCaptureFailed = true;
        return;
    }
    estimatedBytes += listNodeLinkBytes;

    try {
        destination.push_back(value);
        ++data->basicTableRetainedRecords;
        data->basicTableRetainedItems += itemCount;
        data->basicTableRetainedBytes += estimatedBytes;
    } catch (...) {
        data->basicTableCaptureFailed = true;
    }
}

bool estimateRawDxfObjectBytes(
        const DRW_RawDxfObject& raw, std::size_t& estimate) noexcept {
    estimate = sizeof(DRW_RawDxfObject);
    if (!addAssociativeRetainedBytes(raw.name.size() + 1u, estimate)
        || !addAssociativeSlotBytes(raw.groups.size(), sizeof(DRW_Variant),
                                    estimate)
        || !addAssociativeSlotBytes(raw.rawValues.size(), sizeof(UTF8STRING),
                                    estimate))
        return false;
    for (const DRW_Variant& value : raw.groups) {
        if (value.type() == DRW_Variant::STRING) {
            // Copying a Variant string retains bytes after an embedded NUL,
            // even when later wire validation refuses that lexeme. Budget the
            // actual owned allocation before making any replay snapshot.
            const auto* text = value.content.s;
            const std::size_t length = text == nullptr ? 0u : text->size();
            if (!addAssociativeRetainedBytes(
                    length + (text == nullptr ? 0u : 1u), estimate))
                return false;
        } else if (value.type() == DRW_Variant::BINARY) {
            const auto* bytes = value.binary();
            if (bytes != nullptr
                && !addAssociativeRetainedBytes(bytes->size(), estimate))
                return false;
        }
    }
    for (const UTF8STRING& rawValue : raw.rawValues) {
        if (!addAssociativeRetainedBytes(rawValue.size() + 1u, estimate))
            return false;
    }
    return true;
}

bool estimateRawDxfObjectListNodeBytes(
        const DRW_RawDxfObject& raw, std::size_t& estimate) noexcept {
    return estimateRawDxfObjectBytes(raw, estimate)
        && addAssociativeSlotBytes(2u, sizeof(void*), estimate);
}

bool estimateRawDxfSectionBytes(
        const DRW_RawDxfSection& section, std::size_t& estimate) noexcept {
    estimate = sizeof(DRW_RawDxfSection);
    if (!addAssociativeRetainedBytes(section.m_name.size() + 1u, estimate)
        || !addAssociativeSlotBytes(section.m_groups.size(),
                                    sizeof(DRW_Variant), estimate)
        || !addAssociativeSlotBytes(section.m_rawValues.size(),
                                    sizeof(UTF8STRING), estimate))
        return false;
    for (const DRW_Variant& value : section.m_groups) {
        if (value.type() == DRW_Variant::STRING) {
            const char* text = value.c_str();
            const std::size_t length = text == nullptr ? 0u
                : std::char_traits<char>::length(text);
            if (!addAssociativeRetainedBytes(
                    length + (text == nullptr ? 0u : 1u), estimate))
                return false;
        } else if (value.type() == DRW_Variant::BINARY) {
            const auto* bytes = value.binary();
            if (bytes != nullptr
                && !addAssociativeRetainedBytes(bytes->size(), estimate))
                return false;
        }
    }
    for (const UTF8STRING& rawValue : section.m_rawValues) {
        if (!addAssociativeRetainedBytes(rawValue.size() + 1u, estimate))
            return false;
    }
    return true;
}

