bool estimateTableStyleTypedBytes(
        const DRW_TableStyle& style, std::size_t& estimate,
        std::size_t& itemCount) noexcept {
    estimate = sizeof(DRW_TableStyle);
    itemCount = 0;
    const auto addItems = [&itemCount](std::size_t count) {
        if (itemCount > kMaxAdapterTableStyleItems
            || count > kMaxAdapterTableStyleItems - itemCount)
            return false;
        itemCount += count;
        return true;
    };
    const auto addColor = [&estimate](const DRW_TableStyleCmcColor& color) {
        return addStringPayloadBytes(color.m_name, estimate)
            && addStringPayloadBytes(color.m_bookName, estimate);
    };
    const auto addCell = [&estimate, &addItems, &addColor](
            const DRW_TableStyleCellStyle& cell) {
        if (!addVectorPayloadBytes(cell.m_borders, estimate)
            || !addStringPayloadBytes(
                cell.m_contentFormat.m_valueFormatString, estimate)
            || !addColor(cell.m_backgroundColorCmc)
            || !addColor(cell.m_contentFormat.m_contentColorCmc)
            || !addStringPayloadBytes(cell.m_name, estimate)
            || !addItems(cell.m_borders.size()))
            return false;
        for (const DRW_TableStyleBorder& border : cell.m_borders) {
            if (!addColor(border.m_colorCmc))
                return false;
        }
        return true;
    };
    if (!addTableEntryRetainedBytes(style, estimate)
        || !addStringPayloadBytes(style.m_name, estimate)
        || (style.hasDxfDescriptionBaseline()
            && (!addStringPayloadBytes(style.dxfOriginalDescription(),estimate)
                || !addStringPayloadBytes(style.dxfOriginalDescriptionRaw(),estimate)))
        || !addVectorPayloadBytes(style.m_rowStyles, estimate)
        || !addVectorPayloadBytes(style.m_cellStyles, estimate)
        || !addVectorPayloadBytes(style.m_subrecordRanges, estimate)
        || !addCell(style.m_tableCellStyle)
        || !addItems(style.m_rowStyles.size())
        || !addItems(style.m_cellStyles.size())
        || !addItems(style.m_subrecordRanges.size()))
        return false;
    for (const DRW_TableStyleRowStyle& row : style.m_rowStyles) {
        if (!addVectorPayloadBytes(row.m_borders, estimate)
            || !addStringPayloadBytes(row.m_textStyleName, estimate)
            || !addStringPayloadBytes(row.m_valueFormatString, estimate)
            || !addColor(row.m_textColorCmc)
            || !addColor(row.m_fillColorCmc)
            || !addItems(row.m_borders.size()))
            return false;
        for (const DRW_TableStyleBorder& border : row.m_borders) {
            if (!addColor(border.m_colorCmc))
                return false;
        }
    }
    for (const DRW_TableStyleCellStyle& cell : style.m_cellStyles) {
        if (!addCell(cell))
            return false;
    }
    for (const DRW_DwgSubrecordRange& range : style.m_subrecordRanges) {
        if (!addStringPayloadBytes(range.m_name, estimate))
            return false;
    }
    return addAssociativeRetainedBytes(2u * sizeof(void*), estimate);
}

bool estimateCellStyleMapTypedBytes(
        const DRW_CellStyleMap& styleMap, std::size_t& estimate,
        std::size_t& itemCount) noexcept {
    estimate = sizeof(DRW_CellStyleMap);
    itemCount = 0u;
    const auto addItems = [&itemCount](std::size_t count) {
        if (itemCount > kMaxAdapterCellStyleMapItems
            || count > kMaxAdapterCellStyleMapItems - itemCount)
            return false;
        itemCount += count;
        return true;
    };
    const auto addColor = [&estimate](const DRW_TableStyleCmcColor& color) {
        return addStringPayloadBytes(color.m_name, estimate)
            && addStringPayloadBytes(color.m_bookName, estimate);
    };
    const auto addCell = [&estimate, &addItems, &addColor](
            const DRW_TableStyleCellStyle& cell) {
        if (!addVectorPayloadBytes(cell.m_borders, estimate)
            || !addStringPayloadBytes(
                cell.m_contentFormat.m_valueFormatString, estimate)
            || !addColor(cell.m_backgroundColorCmc)
            || !addColor(cell.m_contentFormat.m_contentColorCmc)
            || !addStringPayloadBytes(cell.m_name, estimate)
            || !addItems(cell.m_borders.size()))
            return false;
        for (const DRW_TableStyleBorder& border : cell.m_borders) {
            if (!addColor(border.m_colorCmc))
                return false;
        }
        return true;
    };

    if (!addTableEntryRetainedBytes(styleMap, estimate)
        || !addVectorPayloadBytes(styleMap.m_cellStyles, estimate)
        || !addVectorPayloadBytes(styleMap.m_subrecordRanges, estimate)
        || !addItems(styleMap.m_cellStyles.size())
        || !addItems(styleMap.m_subrecordRanges.size()))
        return false;
    for (const DRW_TableStyleCellStyle& cell : styleMap.m_cellStyles) {
        if (!addCell(cell))
            return false;
    }
    for (const DRW_DwgSubrecordRange& range : styleMap.m_subrecordRanges) {
        if (!addStringPayloadBytes(range.m_name, estimate))
            return false;
    }
    return addAssociativeRetainedBytes(2u * sizeof(void*), estimate);
}

