template <typename Store>
void retainDictionaryTyped(
        dx_data* data, const DRW_Dictionary& dictionary,
        std::size_t listNodeLinkBytes, Store store) {
    if (data == nullptr || data->dictionaryCaptureFailed)
        return;
    const auto reject = [data](bool resourceLimit) {
        data->dictionaryCaptureFailed = true;
        if (data->sourceFormat == dx_source_format::DXF
            && data->associativeDxfImport.generation
                == data->importGeneration) {
            data->associativeDxfImport.resourceLimitExceeded =
                data->associativeDxfImport.resourceLimitExceeded
                || resourceLimit;
            data->associativeDxfImport.captureFailed =
                data->associativeDxfImport.captureFailed || !resourceLimit;
        }
    };
    if (data->dictionaryRetainedRecords
        >= kMaxAdapterDictionaryTypedRecords) {
        reject(true);
        return;
    }

    std::size_t estimatedBytes = 0u;
    std::size_t itemCount = 0u;
    if (!estimateDictionaryTypedBytes(dictionary, estimatedBytes, itemCount)
        || listNodeLinkBytes > kMaxAdapterDictionaryTypedRetainedBytes
        || estimatedBytes > kMaxAdapterDictionaryTypedRetainedBytes
                                - listNodeLinkBytes) {
        reject(true);
        return;
    }
    estimatedBytes += listNodeLinkBytes;
    if (data->dictionaryRetainedEntries
            > kMaxAdapterDictionaryTypedEntries
        || itemCount > kMaxAdapterDictionaryTypedEntries
                            - data->dictionaryRetainedEntries
        || data->dictionaryRetainedBytes
            > kMaxAdapterDictionaryTypedRetainedBytes
        || estimatedBytes > kMaxAdapterDictionaryTypedRetainedBytes
                                - data->dictionaryRetainedBytes) {
        reject(true);
        return;
    }

    try {
        store();
    } catch (...) {
        reject(false);
        return;
    }
    ++data->dictionaryRetainedRecords;
    data->dictionaryRetainedEntries += itemCount;
    data->dictionaryRetainedBytes += estimatedBytes;
}

bool estimateXRecordTypedBytes(
        const DRW_XRecord& record, std::size_t& estimate,
        std::size_t& itemCount) noexcept {
    estimate = sizeof(DRW_XRecord);
    itemCount = 0u;
    const auto addItems = [&itemCount](std::size_t count) {
        if (itemCount > kMaxAdapterXRecordItems
            || count > kMaxAdapterXRecordItems - itemCount)
            return false;
        itemCount += count;
        return true;
    };
    const auto addPayload = [&]() {
        if (!addTableEntryRetainedBytes(record, estimate)
            || !addAssociativeSlotBytes(record.m_handleValues.size(),
                    sizeof(std::pair<int, std::uint32_t>), estimate)
            || !addVectorPayloadBytes(record.m_rawData, estimate)
            || !addItems(record.m_values.size())
            || !addItems(record.m_handleValues.size())
            || !addItems(record.m_dataEntries.size()))
            return false;
        for (const DRW_Variant& value : record.m_values) {
            if (!estimateTableEntryVariantBytes(&value, estimate))
                return false;
        }
        for (const DRW_Variant& value : record.m_dataEntries) {
            if (!estimateTableEntryVariantBytes(&value, estimate))
                return false;
        }
        return true;
    };

    if (!addPayload())
        return false;
    // Parsing unsupported DWG data retains an immutable source snapshot so
    // later edits cannot authorize replay. The snapshot duplicates the public
    // payload; conservatively charge its complete dynamic footprint per
    // callback copy, even though the snapshot allocation is shared.
    if (record.hasDwgRawDataSourceRecord()
        && (!addAssociativeRetainedBytes(sizeof(DRW_XRecord), estimate)
            || !addPayload()))
        return false;
    return estimate <= kMaxAdapterXRecordRetainedBytes;
}

