void retainXRecordTyped(dx_data* data, const DRW_XRecord& record) {
    constexpr std::size_t listNodeLinkBytes = 2u * sizeof(void*);
    if (data == nullptr || data->xRecordCaptureFailed)
        return;
    const auto reject = [data]() { data->xRecordCaptureFailed = true; };
    if (data->xRecordRetainedRecords >= kMaxAdapterXRecordRecords) {
        reject();
        return;
    }

    std::size_t estimatedBytes = 0u;
    std::size_t itemCount = 0u;
    if (!estimateXRecordTypedBytes(record, estimatedBytes, itemCount)
        || estimatedBytes > kMaxAdapterXRecordRetainedBytes
                                - listNodeLinkBytes) {
        reject();
        return;
    }
    estimatedBytes += listNodeLinkBytes;
    if (data->xRecordRetainedItems > kMaxAdapterXRecordItems
        || itemCount > kMaxAdapterXRecordItems - data->xRecordRetainedItems
        || data->xRecordRetainedBytes > kMaxAdapterXRecordRetainedBytes
        || estimatedBytes > kMaxAdapterXRecordRetainedBytes
                                - data->xRecordRetainedBytes) {
        reject();
        return;
    }

    try {
        data->xRecords.push_back(record);
    } catch (...) {
        reject();
        return;
    }
    ++data->xRecordRetainedRecords;
    data->xRecordRetainedItems += itemCount;
    data->xRecordRetainedBytes += estimatedBytes;
}

