void failNamedResourceTypedCapture(
        dx_data& data, bool resourceLimit) noexcept {
    if (resourceLimit)
        data.namedResourceTypedResourceLimitExceeded = true;
    else
        data.namedResourceTypedCaptureFailed = true;
    dx_namedResourceImportReceipt& receipt = data.namedResourceImport;
    if (receipt.generation == data.importGeneration) {
        if (resourceLimit)
            receipt.typedResourceLimitExceeded = true;
        else
            receipt.typedCaptureFailed = true;
    }
}

bool admitNamedResourceTypedCopy(
        dx_data& data, std::size_t retainedBytes) noexcept {
    if (data.namedResourceTypedCaptureFailed
        || data.namedResourceTypedResourceLimitExceeded)
        return false;
    if (data.sourceFormat == dx_source_format::DXF
        && data.importGeneration != 0u
        && data.namedResourceImport.generation != data.importGeneration) {
        failNamedResourceTypedCapture(data, false);
        return false;
    }
    if (data.namedResourceTypedRetainedRecords
            >= kMaxAdapterNamedResourceTypedRecords
        || data.namedResourceTypedRetainedBytes
            > kMaxAdapterNamedResourceTypedRetainedBytes
        || retainedBytes
            > kMaxAdapterNamedResourceTypedRetainedBytes
                - data.namedResourceTypedRetainedBytes) {
        failNamedResourceTypedCapture(data, true);
        return false;
    }
    return true;
}

template <typename Record, typename Estimate>
void retainNamedResourceTyped(
        dx_data* data, std::list<Record>& destination,
        const Record& record, Estimate estimate) {
    constexpr std::size_t listNodeLinkBytes = 2u * sizeof(void*);
    if (data == nullptr || data->namedResourceTypedCaptureFailed
        || data->namedResourceTypedResourceLimitExceeded)
        return;
    std::size_t retainedBytes = 0u;
    if (!estimate(record, retainedBytes)
        || retainedBytes > kMaxAdapterNamedResourceTypedRetainedBytes
            - listNodeLinkBytes) {
        failNamedResourceTypedCapture(*data, true);
        return;
    }
    retainedBytes += listNodeLinkBytes;
    if (!admitNamedResourceTypedCopy(*data, retainedBytes))
        return;
    try {
        destination.push_back(record);
    } catch (...) {
        failNamedResourceTypedCapture(*data, false);
        return;
    }
    ++data->namedResourceTypedRetainedRecords;
    data->namedResourceTypedRetainedBytes += retainedBytes;
}

bool estimateSpatialFilterTypedBytes(
        const DRW_SpatialFilter& filter, std::size_t& estimate) noexcept {
    estimate = sizeof(DRW_SpatialFilter);
    if (!addAssociativeRetainedBytes(filter.name.size() + 1u, estimate)
        || !addAssociativeSlotBytes(filter.reactorHandles.size(),
                                    sizeof(std::uint32_t), estimate)
        || !addAssociativeSlotBytes(filter.pendingAppIdResolutions.size(),
                sizeof(DRW_TableEntry::PendingHandleRef), estimate)
        || !addAssociativeSlotBytes(filter.pendingLayerRefResolutions.size(),
                sizeof(DRW_TableEntry::PendingHandleRef), estimate)
        || !addAssociativeSlotBytes(filter.extData.size(),
                                    sizeof(DRW_Variant*), estimate)
        || !addAssociativeSlotBytes(filter.appData.size(),
                sizeof(std::list<DRW_Variant>), estimate)
        || !addAssociativeSlotBytes(filter.m_boundaryPoints.size(),
                                    sizeof(DRW_Coord), estimate)
        || !addAssociativeSlotBytes(filter.m_inverseInsertTransform.size(),
                                    sizeof(double), estimate)
        || !addAssociativeSlotBytes(filter.m_insertTransform.size(),
                                    sizeof(double), estimate))
        return false;
    for (const DRW_Variant* value : filter.extData) {
        if (!estimateAssociativeVariantBytes(value, estimate))
            return false;
    }
    for (const auto& appGroup : filter.appData) {
        for (const DRW_Variant& value : appGroup) {
            if (!estimateAssociativeVariantBytes(&value, estimate))
                return false;
        }
    }
    return estimate <= kMaxAdapterSpatialFilterRetainedBytes;
}

