bool estimateDynamicBlockTypedBytes(
        const DRW_DynamicBlockObject& object,
        std::size_t& estimate) noexcept {
    estimate = sizeof(DRW_DynamicBlockObject);
    if (!addTableEntryRetainedBytes(object, estimate))
        return false;

    const UTF8STRING* strings[] = {
        &object.m_recordName,
        &object.m_elementName,
        &object.m_gripExpr,
        &object.m_flipCaption,
        &object.m_flipDescription,
        &object.m_flipBaseStateName,
        &object.m_flipFlippedStateName,
        &object.m_flipTooltip,
        &object.m_rotationAngleName,
        &object.m_rotationAngleDescription,
        &object.m_linearDistanceName,
        &object.m_linearDistanceDescription,
        &object.m_polarAngleName,
        &object.m_polarAngleDescription,
        &object.m_polarDistanceName,
        &object.m_polarDistanceDescription,
        &object.m_xyXLabel,
        &object.m_xyXDescription,
        &object.m_xyYLabel,
        &object.m_xyYDescription,
        &object.m_constraintExpressionName,
        &object.m_constraintExpressionDescription,
        &object.m_positionName,
        &object.m_positionDescription,
        &object.m_lookupName,
        &object.m_lookupDescription,
        &object.m_lookupUnknownText,
        &object.m_visibilityName,
        &object.m_visibilityDescription,
        &object.m_rotateConnectionName,
        &object.m_dependencyName};
    for (const UTF8STRING* value : strings) {
        if (!addStringPayloadBytes(*value, estimate))
            return false;
    }

    if (!addVectorPayloadBytes(object.m_propertyInfo1Codes, estimate)
        || !addStringVectorPayloadBytes(object.m_propertyInfo1Names, estimate)
        || !addVectorPayloadBytes(object.m_propertyInfo2Codes, estimate)
        || !addStringVectorPayloadBytes(object.m_propertyInfo2Names, estimate)
        || !addVectorPayloadBytes(object.m_rotationValues, estimate)
        || !addVectorPayloadBytes(object.m_linearValues, estimate)
        || !addVectorPayloadBytes(object.m_polarAngleValues, estimate)
        || !addVectorPayloadBytes(object.m_polarDistanceValues, estimate)
        || !addVectorPayloadBytes(object.m_xyXValues, estimate)
        || !addVectorPayloadBytes(object.m_xyYValues, estimate)
        || !addVectorPayloadBytes(object.m_constraintValues, estimate)
        || !addStringVectorPayloadBytes(object.m_stateNames, estimate)
        || !addVectorPayloadBytes(object.m_blockHandles, estimate)
        || !addNestedVectorPayloadBytes(object.m_stateBlockHandles, estimate)
        || !addNestedVectorPayloadBytes(
                object.m_stateParameterHandles, estimate)
        || !addVectorPayloadBytes(object.m_dependencyHandles, estimate)
        || !addVectorPayloadBytes(object.m_actionIndexes, estimate)
        || !addStringVectorPayloadBytes(object.m_connectionNames, estimate)
        || !addVectorPayloadBytes(object.m_connectionCodes, estimate)
        || !addStringVectorPayloadBytes(
                object.m_rotateBaseConnectionNames, estimate)
        || !addVectorPayloadBytes(
                object.m_rotateBaseConnectionCodes, estimate)
        || !addStringVectorPayloadBytes(object.m_lookupExpressions, estimate)
        || !addNestedVectorPayloadBytes(
                object.m_lookupConnectionCodes, estimate)
        || !addNestedStringVectorPayloadBytes(
                object.m_lookupConnectionNames, estimate)
        || !addVectorPayloadBytes(object.m_lookupEntryFlags282, estimate)
        || !addVectorPayloadBytes(object.m_lookupEntryFlags281, estimate)
        || !addVectorPayloadBytes(object.m_polarStretchPoints, estimate)
        || !addVectorPayloadBytes(object.m_polarStretchHandles, estimate)
        || !addVectorPayloadBytes(
                object.m_polarStretchHandleShorts, estimate)
        || !addVectorPayloadBytes(object.m_polarStretchCodes, estimate)
        || !addStringVectorPayloadBytes(object.m_baseConnectionNames, estimate)
        || !addVectorPayloadBytes(object.m_baseConnectionCodes, estimate)
        || !addStringVectorPayloadBytes(
                object.m_scaleConnectionNames, estimate)
        || !addVectorPayloadBytes(object.m_scaleConnectionCodes, estimate)
        || !addVectorPayloadBytes(object.m_stretchPoints, estimate)
        || !addVectorPayloadBytes(
                object.m_handleReferenceHandles, estimate)
        || !addVectorPayloadBytes(
                object.m_handleReferenceIndexCounts, estimate)
        || !addNestedVectorPayloadBytes(
                object.m_handleReferenceIndexes, estimate)
        || !addVectorPayloadBytes(object.m_codeReferenceCodes, estimate)
        || !addVectorPayloadBytes(
                object.m_codeReferenceIndexCounts, estimate)
        || !addNestedVectorPayloadBytes(
                object.m_codeReferenceIndexes, estimate))
        return false;

    for (std::size_t index = 0;
         index < object.m_twoPointPropertyCodes.size(); ++index) {
        if (!addVectorPayloadBytes(
                object.m_twoPointPropertyCodes[index], estimate)
            || !addStringVectorPayloadBytes(
                object.m_twoPointPropertyNames[index], estimate))
            return false;
    }
    return estimate <= kMaxAdapterDynamicBlockRetainedBytes;
}

