    m_dxfMLineLinetypes.clear();m_dxfMLineLinetypesInspected=false;m_dxfMLineLinetypeCount=0u;
    m_mlineStyleNamesToWrite.clear();m_dxfMLineConsumers.clear();m_dxfMLineConsumerInspected=0u;
    if (!cData) return false;
