void dx_iface::finishTableReferences(dx_data& data) noexcept {
    using A=dx_data::TableDxfSourceCapture::TableReferenceAudit;using S=A::State;using R=A::Reason;
    using Role=dx_attdef_source::Role;using I=DRW_DxfIdentitySource;
    auto& s=data.m_tableDxfSource;if(s.tableReferenceCaptureFailed)return;
    const auto selected=[](Role role){return role==Role::TableStyle||role==Role::TableGeometryBlock||role==Role::TableCellBlock
        ||role==Role::TableCellField||role==Role::TableCellAttributeDefinition||role==Role::TableValueObject;};
    try {
        std::size_t groups=0u,candidates=s.structuralAudits.size(),bytes=sizeof(A)+32u*sizeof(void*),work=256u;
        for(const auto& item:s.tableBodies)if(!item.second||item.second->profiles.empty()
            ||!addAssociativeRetainedBytes(item.second->profiles.front().spans.size(),groups)){s.tableReferenceCaptureFailed=true;return;}
        if(!addAssociativeRetainedBytes(s.layoutAudits.size(),candidates)||!addAssociativeRetainedBytes(s.resourceOriginAudits.size(),candidates)
            ||(s.plotSourceAudit&&!addAssociativeRetainedBytes(s.plotSourceAudit->records.size(),candidates))
            ||(s.viewUcsAudit&&!addAssociativeRetainedBytes(s.viewUcsAudit->records.size(),candidates))
            ||(s.renderingSourceAudit&&!addAssociativeRetainedBytes(s.renderingSourceAudit->records.size(),candidates))
            ||(s.entitiesRoleAudit&&!addAssociativeRetainedBytes(s.entitiesRoleAudit->rows.size(),candidates))
            ||(s.blockRoleAudit&&!addAssociativeRetainedBytes(s.blockRoleAudit->rows.size(),candidates))
            ||!addAssociativeSlotBytes(groups,128u,work)||!addAssociativeSlotBytes(candidates,128u,work)
            ||work>s.maxTableReferenceWork){s.tableReferenceCaptureFailed=true;return;}
        // Charge the linear inventory pass before examining individual spans.
        s.tableReferenceWork=work;std::size_t rows=0u;
        for(const auto& item:s.tableBodies)for(const auto& span:item.second->profiles.front().spans)if(selected(span.role)) {
            if(rows>=s.maxTableReferenceRows){s.tableReferenceCaptureFailed=true;return;}++rows;
        }
        if(!addAssociativeSlotBytes(rows,sizeof(A::Row),bytes)
            ||!addAssociativeSlotBytes(candidates,sizeof(A::Target)+sizeof(std::uint32_t)+8u*sizeof(void*),bytes)
            ||!addAssociativeSlotBytes(s.tableBodies.size(),sizeof(std::shared_ptr<const TableBody>),bytes)
            ||bytes>s.maxTableReferenceBytes||!addAssociativeRetainedBytes(bytes,work)||work>s.maxTableReferenceWork) {
            s.tableReferenceCaptureFailed=true;return;
        }
        s.tableReferenceBytes=bytes;s.tableReferenceWork=work;
        auto audit=std::make_shared<A>();audit->container=&data;audit->generation=s.generation;audit->containerId=data.m_entitiesContainerIdentity.value;
        audit->identity=s.identityInput;audit->identities=s.identityAudit;audit->entities=s.entitiesRoleAudit;audit->blocks=s.blockRoleAudit;audit->plots=s.plotSourceAudit;audit->views=s.viewUcsAudit;audit->renderings=s.renderingSourceAudit;
        audit->tables.reserve(s.tableBodies.size());audit->rows.reserve(rows);
        for(const auto& item:s.tableBodies)audit->tables.push_back(item.second);
        const auto save=[&](S state){audit->state=state;s.tableReferenceAudit=std::move(audit);s.tableReferenceOwner=s.tableReferenceAudit;};
        const auto body=tableBodyReport(data);
        if((!s.tableBodies.empty()&&(!body.modeledMatched||!body.profilesMatched))||identitySourceReport(data).state!=IdentitySourceState::NamespaceReady) {save(S::SourceNotReady);return;}
        const auto structural=structuralSourceReport(data);const auto layout=layoutSourceReport(data);const auto resources=resourceOriginReport(data);
        const auto entities=entitiesRoleReport(data);const auto blocks=blockRoleReport(data);
        if(structural.state==StructuralSourceState::ContextMismatch||layout.state==LayoutSourceState::ContextMismatch
            ||entities.state==EntitiesRoleState::ContextMismatch||blocks.state==BlockRoleState::ContextMismatch||resources.state==ResourceOriginState::ContextMismatch) {save(S::ContextMismatch);return;}
        const auto& source=*audit->identity->source;
        const auto add=[&](std::uint32_t handle,A::Target target) {
            const auto id=audit->identities->identities.find(handle);
            if(!handle||id==audit->identities->identities.end()||id->second>=source.records.size()||id->second!=target.physical)return;
            const auto inserted=audit->targets.emplace(handle,std::move(target));if(!inserted.second)inserted.first->second.ambiguous=true;
        };
        if(structural.state!=StructuralSourceState::CaptureFailed)for(const auto& item:s.structuralAudits) {
            const auto& a=item.second;if(!a||!a->originBound||!a->bodyMatched||!a->stateComplete||!a->input||!a->input->paired)continue;
            A::Target target;target.provider=A::Provider::Structural;target.physical=a->physical;target.structural=a;add(item.first,std::move(target));
        }
        if(layout.state!=LayoutSourceState::CaptureFailed)for(const auto& item:s.layoutAudits) {
            const auto& a=item.second;if(!a||a->state!=dx_data::TableDxfSourceCapture::LayoutAudit::State::Matched)continue;
            const auto id=audit->identities->identities.find(item.first);if(id==audit->identities->identities.end()||id->second>=source.records.size())continue;
            const auto& p=source.records[id->second];if(p.kind!=I::Kind::Object||!asciiIdentifierEquals(p.name,"LAYOUT"))continue;
            A::Target target;target.provider=A::Provider::Layout;target.physical=id->second;target.layout=a;add(item.first,std::move(target));
        }
        if(resources.state!=ResourceOriginState::CaptureFailed)for(const auto& item:s.resourceOriginAudits) {
            const auto& a=item.second;if(!a||!a->originBound||!a->bodyMatched||!a->stateComplete||!a->input||!a->input->paired)continue;
            A::Target target;target.provider=A::Provider::Resource;target.physical=a->physical;target.resource=a;add(item.first,std::move(target));
        }
        const auto plots=plotStyleSourceReport(data);
        if(audit->plots&&plots.state!=PlotSourceState::ContextMismatch&&plots.state!=PlotSourceState::CaptureFailed&&plots.state!=PlotSourceState::SourceNotReady)
            for(const auto& item:audit->plots->records) {
                const auto& row=item.second;if(!row->bodyMatched||!row->originBound)continue;
                A::Target target;target.provider=A::Provider::PlotSource;target.physical=row->physical;target.plot=row;add(item.first,std::move(target));
            }
        const auto views=viewUcsSourceReport(data);
        if(audit->views&&views.state!=ViewUcsState::ContextMismatch&&views.state!=ViewUcsState::CaptureFailed&&views.state!=ViewUcsState::SourceNotReady)
            for(const auto& item:audit->views->records){const auto& row=item.second;if(!row->bodyMatched||!row->originBound||!row->stateComplete)continue;
                A::Target target;target.provider=A::Provider::ViewUcs;target.physical=row->physical;target.viewUcs=row;add(item.first,std::move(target));}
        const auto renderings=renderingSourceReport(data);
        if(audit->renderings&&renderings.state!=RenderingSourceState::ContextMismatch&&renderings.state!=RenderingSourceState::CaptureFailed
            &&renderings.state!=RenderingSourceState::Limited&&renderings.state!=RenderingSourceState::SourceNotReady)
            for(const auto& item:audit->renderings->records){const auto& row=item.second;if(!row->bodyMatched||!row->originBound)continue;
                A::Target target;target.provider=A::Provider::Rendering;target.physical=row->physical;target.rendering=row;add(item.first,std::move(target));}
        if(audit->entities&&entities.state!=EntitiesRoleState::CaptureFailed&&entities.state!=EntitiesRoleState::SourceNotReady)
            for(const auto& row:audit->entities->rows)if(row.reason==dx_data::TableDxfSourceCapture::EntitiesRoleAudit::Reason::Matched) {
                A::Target target;target.provider=A::Provider::Entities;target.physical=row.physical;target.block=row.block;add(row.self,std::move(target));
            }
        if(audit->blocks&&blocks.state!=BlockRoleState::CaptureFailed&&blocks.state!=BlockRoleState::SourceNotReady)
            for(const auto& row:audit->blocks->rows)if(row.reason==dx_data::TableDxfSourceCapture::BlockRoleAudit::Reason::Matched) {
                A::Target target;target.provider=A::Provider::Blocks;target.physical=row.physical;target.block=row.block;add(row.self,std::move(target));
            }
        if(s.tableBodies.empty()){save(s.tableInputs.empty()?S::NoTables:S::SourceNotReady);return;}
        bool complete=true;
        for(const auto& table:audit->tables) {
            const auto& physical=table->source->inBlock?table->source->blockPhysical->records[table->first]:table->entitiesPhysical->records[table->first];
            std::uint32_t cellBlock=0u;
            for(const auto& span:table->profiles.front().spans) {
                if(span.code==171&&span.field==dx_attdef_source::Field::TableCell)cellBlock=0u;
                if(!selected(span.role))continue;
                A::Row row;row.table=table->source->model->handle;row.target=static_cast<std::uint32_t>(span.handle);row.group=span.groupIndex;row.role=span.role;
                if(span.groupIndex>=physical.groups.size()){save(S::ContextMismatch);return;}
                if(span.role==Role::TableCellBlock)cellBlock=row.target;row.cellBlock=cellBlock;
                if(!row.target)row.reason=span.role==Role::TableValueObject?R::NullValue:R::NullRequired;
                else {
                    const auto id=audit->identities->identities.find(row.target);
                    if(id==audit->identities->identities.end())row.reason=R::MissingTarget;
                    else {
                        row.physical=id->second;const auto& target=source.records[id->second];
                        const bool block=span.role==Role::TableGeometryBlock||span.role==Role::TableCellBlock;
                        const bool kind=span.role==Role::TableValueObject
                            ||(block&&target.kind==I::Kind::TableRecord&&asciiIdentifierEquals(target.name,"BLOCK_RECORD"))
                            ||(span.role==Role::TableStyle&&target.kind==I::Kind::Object&&asciiIdentifierEquals(target.name,"TABLESTYLE"))
                            ||(span.role==Role::TableCellField&&target.kind==I::Kind::Object&&resourceOriginName(dxfRW::DxfResourceSourceView::Kind::Field,target.name))
                            ||(span.role==Role::TableCellAttributeDefinition&&target.kind==I::Kind::Entity&&asciiIdentifierEquals(target.name,"ATTDEF"));
                        const auto proof=audit->targets.find(row.target);
                        if(!kind)row.reason=R::WrongKind;
                        else if(proof==audit->targets.end())row.reason=R::OriginalTargetUnavailable;
                        else if(proof->second.ambiguous)row.reason=R::AmbiguousOrigin;
                        else if(proof->second.physical!=row.physical)row.reason=R::OriginalTargetUnavailable;
                        else if(span.role==Role::TableCellAttributeDefinition&&(!cellBlock||proof->second.block!=cellBlock))row.reason=R::WrongCellBlock;
                        else row.reason=R::Matched;
                    }
                }
                complete=complete&&(row.reason==R::Matched||row.reason==R::NullValue);audit->rows.push_back(row);
            }
        }
        save(audit->rows.empty()?S::NoReferences:complete?S::ReferencesReady:S::Unqualified);
    }catch(...){s.tableReferenceCaptureFailed=true;}
}

dx_iface::TableReferenceReport dx_iface::tableReferenceReport(const dx_data& data) noexcept {
    using A=dx_data::TableDxfSourceCapture::TableReferenceAudit;using S=A::State;using R=A::Reason;TableReferenceReport r;
    const auto& s=data.m_tableDxfSource;r.bytes=s.tableReferenceBytes;r.work=s.tableReferenceWork;
    if(!s.generation||data.sourceFormat!=dx_source_format::DXF)return r;
    if(!s.closed){r.state=S::Reading;return r;}if(!s.successful){r.state=S::ImportFailed;return r;}
    if(s.contextFailed||s.generation!=1u||s.generation!=data.importGeneration||s.reader||s.entitiesReadInput){r.state=S::ContextMismatch;return r;}
    if(s.tableReferenceCaptureFailed){r.state=S::CaptureFailed;return r;}const auto& a=s.tableReferenceAudit;if(!a)return r;
    const auto same=[](const auto& x,const auto& y){return x.get()==y.get()&&!x.owner_before(y)&&!y.owner_before(x);};
    if(!same(a,s.tableReferenceOwner)||a->container!=&data||a->generation!=s.generation||a->containerId!=data.m_entitiesContainerIdentity.value
        ||!same(a->identity,s.identityInput)||!same(a->identities,s.identityAudit)||!same(a->entities,s.entitiesRoleAudit)||!same(a->blocks,s.blockRoleAudit)||!same(a->plots,s.plotSourceAudit)
        ||!same(a->views,s.viewUcsAudit)||!same(a->renderings,s.renderingSourceAudit)||a->tables.size()!=s.tableBodies.size()){r.state=S::ContextMismatch;return r;}
    std::size_t index=0u;for(const auto& table:s.tableBodies)if(!same(table.second,a->tables[index++])){r.state=S::ContextMismatch;return r;}
    const auto identity=identitySourceReport(data);const auto structural=structuralSourceReport(data);const auto layout=layoutSourceReport(data);const auto resources=resourceOriginReport(data);
    const auto entities=entitiesRoleReport(data);const auto blocks=blockRoleReport(data);const auto body=tableBodyReport(data);
    const auto plots=plotStyleSourceReport(data);
    const auto views=viewUcsSourceReport(data);
    const auto renderings=renderingSourceReport(data);
    if(identity.state==IdentitySourceState::ContextMismatch||structural.state==StructuralSourceState::ContextMismatch||layout.state==LayoutSourceState::ContextMismatch
        ||entities.state==EntitiesRoleState::ContextMismatch||blocks.state==BlockRoleState::ContextMismatch||body.state==TableBodyState::ContextMismatch
        ||resources.state==ResourceOriginState::ContextMismatch||plots.state==PlotSourceState::ContextMismatch||views.state==ViewUcsState::ContextMismatch
        ||renderings.state==RenderingSourceState::ContextMismatch){r.state=S::ContextMismatch;return r;}
    for(const auto& item:a->targets) {
        const auto& target=item.second;
        if(target.structural) {const auto found=s.structuralAudits.find(item.first);
            if(found==s.structuralAudits.end()||!same(target.structural,found->second)){r.state=S::ContextMismatch;return r;}}
        if(target.layout) {const auto found=s.layoutAudits.find(item.first);
            if(found==s.layoutAudits.end()||!same(target.layout,found->second)){r.state=S::ContextMismatch;return r;}}
        if(target.viewUcs){if(!a->views||views.state==ViewUcsState::CaptureFailed||views.state==ViewUcsState::SourceNotReady){r.state=S::SourceNotReady;return r;}
            const auto found=a->views->records.find(item.first);if(found==a->views->records.end()||!same(target.viewUcs,found->second)){r.state=S::ContextMismatch;return r;}}
        if(target.resource) {const auto found=s.resourceOriginAudits.find(item.first);
            if(found==s.resourceOriginAudits.end()||!same(target.resource,found->second)){r.state=S::ContextMismatch;return r;}}
        if(target.plot) {
            if(!a->plots||plots.state==PlotSourceState::CaptureFailed||plots.state==PlotSourceState::SourceNotReady){r.state=S::SourceNotReady;return r;}
            const auto found=a->plots->records.find(item.first);
            if(found==a->plots->records.end()||!same(target.plot,found->second)){r.state=S::ContextMismatch;return r;}}
        if(target.rendering){if(!a->renderings||renderings.state==RenderingSourceState::CaptureFailed||renderings.state==RenderingSourceState::Limited||renderings.state==RenderingSourceState::SourceNotReady){r.state=S::SourceNotReady;return r;}
            const auto found=a->renderings->records.find(item.first);if(found==a->renderings->records.end()||!same(target.rendering,found->second)){r.state=S::ContextMismatch;return r;}}
    }
    if(a->state!=S::NoTables&&a->state!=S::SourceNotReady
        &&(identity.state!=IdentitySourceState::NamespaceReady||!body.modeledMatched||!body.profilesMatched
            ||structural.state==StructuralSourceState::CaptureFailed||layout.state==LayoutSourceState::CaptureFailed
            ||entities.state==EntitiesRoleState::CaptureFailed||blocks.state==BlockRoleState::CaptureFailed
            ||entities.state==EntitiesRoleState::SourceNotReady||blocks.state==BlockRoleState::SourceNotReady
            ||resources.state==ResourceOriginState::CaptureFailed||resources.state==ResourceOriginState::SourceNotReady)){r.state=S::SourceNotReady;return r;}
    r.state=a->state;r.tables=a->tables.size();r.references=a->rows.size();r.targets=a->targets.size();
    for(const auto& row:a->rows) {
        const bool matched=row.reason==R::Matched||row.reason==R::NullValue;
        if(matched)++r.matched;else if(!r.firstTable){r.firstTable=row.table;r.firstTarget=row.target;}
        if(row.role==dx_attdef_source::Role::TableValueObject){++r.values;if(matched)++r.matchedValues;}
        switch(row.reason) {case R::Matched:break;case R::NullValue:++r.nullValues;break;case R::NullRequired:++r.nullRequired;break;
        case R::MissingTarget:++r.missing;break;case R::WrongKind:++r.wrongKind;break;case R::OriginalTargetUnavailable:++r.unavailable;break;
        case R::AmbiguousOrigin:++r.ambiguous;break;case R::WrongCellBlock:++r.wrongCellBlock;break;}
    }
    r.sourceTargetsMatched=r.state==S::ReferencesReady&&r.references&&r.references==r.matched;
    r.valueSourceTargetsMatched=(r.state==S::ReferencesReady||r.state==S::Unqualified)&&r.values&&r.values==r.matchedValues;return r;
}

#include "dx_dependency_audit.h"

bool dx_iface::chargeTableSource(
        std::size_t bytes, std::size_t groups, std::size_t records) noexcept {
    if (!cData) return false;
    auto& source = cData->m_tableDxfSource;
    if (!tableSourceCaptureOpen()) {
        source.contextFailed = true;
        return false;
    }
    // Conservative map-node/key/alignment overhead for each owned record.
    if (!addAssociativeSlotBytes(records, 8u * sizeof(void*), bytes)
        || source.records > source.maxRecords || records > source.maxRecords - source.records
        || source.groups > source.maxGroups || groups > source.maxGroups - source.groups
        || source.bytes > source.maxBytes || bytes > source.maxBytes - source.bytes) {
        source.failed = true;
        return false;
    }
    source.records += records;
    source.groups += groups;
    source.bytes += bytes;
    return true;
}

void dx_iface::addDxfTableSource(const DRW_Table& table,
                                const DRW_RawDxfObject& raw) {
    captureTableInput(table,&raw,false);
    observeDxfBlockDeliveryValue(static_cast<std::int32_t>(table.eType),table.handle,table.parentHandle,
                                DRW_DxfBlockCallback::TableSource,&raw,&table);
    observeDxfEntitiesTyped<DRW_Table>(table,DRW_DxfEntitiesCallback::TableSource);
    observeDxfEntitiesRaw(raw,DRW_DxfEntitiesCallback::TableSource);
    if (!cData) return;
    auto& source = cData->m_tableDxfSource;
    if (!tableSourceCaptureOpen()) { source.contextFailed = true; return; }
    std::size_t bytes = 0u, rawBytes = 0u;
    if (!estimateTypedEntityRetainedBytes(table, sizeof(DRW_Table), bytes)
        || !estimateRawDxfObjectBytes(raw, rawBytes)
        || !addAssociativeRetainedBytes(rawBytes, bytes)) {
        source.failed = true;
        return;
    }
    if (!chargeTableSource(bytes, raw.groups.size(), 2u)) return;
    try {
        if (!source.tables.try_emplace(table.handle, table, raw).second)
            source.failed = true;
    } catch (...) { source.failed = true; }
}

void dx_iface::retainTableSourceDictionary(const DRW_Dictionary& data) {
    if (!tableSourceCaptureOpen()) return;
    auto& source = cData->m_tableDxfSource;
    if (source.selectionWork > source.maxWork
        || data.m_entries.size() > source.maxWork - source.selectionWork) {
        source.failed = true; return;
    }
    source.selectionWork += data.m_entries.size();
    const bool selected = std::any_of(data.m_entries.begin(), data.m_entries.end(),
        [](const DRW_Dictionary::Entry& entry) { return entry.m_name == "ACAD_XREC_ROUNDTRIP"; });
    if (!selected) return;
    std::size_t bytes = 0u, items = 0u;
    if (!estimateDictionaryTypedBytes(data, bytes, items)
        || !addTableSourceObjectNodeBytes(data, bytes)) { source.failed = true; return; }
    if (!chargeTableSource(bytes, 0u)) return;
    try {
        if (!source.dictionaries.emplace(data.handle, data).second) source.failed = true;
    } catch (...) { source.failed = true; }
}

void dx_iface::retainTableSourceXRecord(const DRW_XRecord& data) {
    if (!tableSourceCaptureOpen()) return;
    auto& source = cData->m_tableDxfSource;
    if (source.selectionWork > source.maxWork
        || data.m_dataEntries.size() > source.maxWork - source.selectionWork) {
        source.failed = true; return;
    }
    source.selectionWork += data.m_dataEntries.size();
    const bool selected = std::any_of(data.m_dataEntries.begin(), data.m_dataEntries.end(),
        [](const DRW_Variant& value) {
            return value.code() == 102 && value.type() == DRW_Variant::STRING
                && value.content.s && *value.content.s == "ACAD_ROUNDTRIP_2008_TABLE_ENTITY";
        });
    if (!selected) return;
    std::size_t bytes = 0u, items = 0u;
    if (!estimateXRecordTypedBytes(data, bytes, items)
        || !addTableSourceObjectNodeBytes(data, bytes)) { source.failed = true; return; }
    if (!chargeTableSource(bytes, 0u)) return;
    try {
        if (!source.xrecords.emplace(data.handle, data).second) source.failed = true;
    } catch (...) { source.failed = true; }
}

bool dx_iface::retainTableSourceRaw(const DRW_RawDxfObject& data) {
    const bool content = asciiIdentifierEquals(data.name, "TABLECONTENT")
        || asciiIdentifierEquals(data.name, "ACDBTABLECONTENT");
    const bool geometry = asciiIdentifierEquals(data.name, "TABLEGEOMETRY")
        || asciiIdentifierEquals(data.name, "ACDBTABLEGEOMETRY");
    if (content) cData->standaloneTableContentPresent = true;
    if (geometry) cData->standaloneTableGeometryPresent = true;
    if (!tableSourceCaptureOpen()) return content || geometry;
    auto& source = cData->m_tableDxfSource;
    const bool selected = content || geometry
        || (asciiIdentifierEquals(data.name, "DICTIONARY") && source.dictionaries.count(data.handle))
        || (asciiIdentifierEquals(data.name, "XRECORD") && source.xrecords.count(data.handle));
    if (!selected) return false;
    std::size_t bytes = 0u;
    if (!estimateRawDxfObjectBytes(data, bytes)) { source.failed = true; return content || geometry; }
    const bool contentProof=content && source.contents.count(data.handle)!=0u;
    if (contentProof && (!addAssociativeRetainedBytes(
            sizeof(std::vector<dxfTableContent::Reference>)+8u*sizeof(void*),bytes)
        || !addAssociativeSlotBytes(data.groups.size(),sizeof(dxfTableContent::Reference),bytes))) {
        source.failed=true; return true;
    }
    if (!chargeTableSource(bytes, data.groups.size())) return content || geometry;
    try {
        if (!source.rawObjects.emplace(data.handle, data).second) source.failed = true;
        else if (contentProof) (void)proveTableContentSource(data);
    } catch (...) { source.failed = true; }
    // Wrappers still need their established editable/output lane. Children
    // have no output lane and are retained only in this private source capture.
    return content || geometry;
}

bool dx_iface::proveTableContentSource(const DRW_RawDxfObject& raw) {
    auto& source=cData->m_tableDxfSource;
    // Reserve a conservative scalar-comparison budget and the decoder's
    // pairwise merged-range checks before reparsing or allocating companions.
    const auto cap=source.maxContentProofWork;
    if (raw.groups.size()>cap/64u) {source.failed=true;return false;}
    const auto slots=raw.groups.size()*64u;
    if (source.contentProofWork>cap-slots) {source.failed=true;return false;}
    source.contentProofWork+=slots;
    std::size_t ranges=0u, end=raw.groups.size()>=2u?raw.groups.size()-2u:0u;
    while (end>=4u && raw.groups[end-4u].code()==91 && raw.groups[end-3u].code()==92
            && raw.groups[end-2u].code()==93 && raw.groups[end-1u].code()==94) {
        ++ranges; end-=4u;
    }
    if (ranges>10000u) {source.failed=true; return false;}
    const auto pairs=ranges*(ranges-std::min(ranges,std::size_t{1}))/2u;
    if (pairs>cap-source.contentProofWork) {
        source.failed=true; return false;
    }
    source.contentProofWork+=pairs;
    if (!tableSourceRawSpellingsEqual(raw,source.maxBytes)) {
        source.contentPayloadMismatch=true; return false;
    }
    struct Roles final : dxfTableContent::ReferenceSink {
        std::vector<dxfTableContent::Reference> values;
        std::size_t cap;
        explicit Roles(std::size_t size) : cap(size) {values.reserve(size);}
        bool add(const dxfTableContent::Reference& value) override {
            if (values.size()==cap) return false;
            values.push_back(value); return true;
        }
    } roles(raw.groups.size()); // capacity/overhead precharged with raw copy
    const char* version=nullptr;
    switch (raw.m_version) {
    case DRW::AC1021:version="AC1021";break;
    case DRW::AC1024:version="AC1024";break;
    case DRW::AC1027:version="AC1027";break;
    case DRW::AC1032:version="AC1032";break;
    default:source.contentPayloadMismatch=true;return false;
    }
    std::istringstream empty;
    std::unique_ptr<dxfReader> decoder;
    if (raw.hasRawValues) decoder=std::make_unique<dxfReaderAscii>(&empty);
    else decoder=std::make_unique<dxfReaderBinary>(&empty);
    auto budget=std::make_shared<DxfReadRetainedBudget>(source.maxBytes);
    decoder->setRetainedByteBudget(budget);
    decoder->setTypedVariantNodeBudget(cap);
    decoder->setVersion(version,true);
    DRW_TableContentObject parsed;
    const bool decoded=dxfTableContent::Decoder(raw,*decoder,&roles).decode(parsed);
    const auto original=source.contents.find(raw.handle);
    if (budget->exceeded() || decoder->typedVariantNodeBudgetExceeded()) {source.failed=true; return false;}
    if (!decoded || original==source.contents.end()
        || !standardDwgCommonEqual(parsed,original->second,raw.m_version)
        || parsed.m_parseComplete!=original->second.m_parseComplete
        || parsed.m_semanticContentComplete!=original->second.m_semanticContentComplete
        || !parsed.m_dxfMetadata || !original->second.m_dxfMetadata
        || !tableSourceContentCoreEqual(parsed.m_content,original->second.m_content)
        || !tableSourceMetadataEqual(*parsed.m_dxfMetadata,*original->second.m_dxfMetadata)) {
        source.contentPayloadMismatch=true; return false;
    }
    if (!source.contentReferences.emplace(raw.handle,std::move(roles.values)).second) {
        source.contentPayloadMismatch=true; return false;
    }
    return true;
}

void dx_iface::finishTableSourceRead(bool success) noexcept {
    if (!m_tableSourceReadData) return;
    auto& data = *m_tableSourceReadData;
    auto& source = data.m_tableDxfSource;
    if(!source.tablePendingInputs.empty())source.tableInputIncomplete=true;
    source.tablePendingInputs.clear();
    if(!source.resourceOriginPending.empty())source.resourceOriginCaptureFailed=true;
    source.resourceOriginPending.clear();
    if(source.attdefPending)source.resourceProofCaptureFailed=true;
    if(source.blockSourcePending||source.blockSourceActive)source.blockSourceCaptureFailed=true;
    if(source.entitiesPending.scope)source.entitiesDeliveryCaptureFailed=true;
    source.closed = true;
    source.successful = success && data.sourceFormat == dx_source_format::DXF
        && data.dxfReadOutcome.operationSucceeded && !data.dxfReadOutcome.readThrew
        && data.dxfReadOutcome.error == DRW::BAD_NONE;
    source.version = source.successful ? data.sourceVersion : DRW::UNKNOWNV;
    source.reader = nullptr;
    source.entitiesReadInput = nullptr;
    m_tableSourceReadData = nullptr;
    if(source.successful)finishTableBodies(data);
    if(source.successful)finishEntitiesCompoundAudits(data);
    if(source.layoutPendingHandle||source.layoutPendingModel)source.layoutCaptureFailed=true;
    source.layoutPendingHandle=0u;source.layoutPendingModel=nullptr;
    if(source.successful)finishLayoutSourceAudits(data);
    if(source.successful)finishIdentitySourceAudit(data);
    if(source.successful)finishResourceOrigins(data);
    if(!source.structuralPending.empty())source.structuralCaptureFailed=true;
    source.structuralPending.clear();
    if(source.successful)finishStructuralSourceAudits(data);
    if(!source.plotSourcePending.empty())source.plotSourceCaptureFailed=true;
    source.plotSourcePending.clear();
    if(source.successful)finishPlotStyleSources(data);
    if(!source.viewUcsPending.empty())source.viewUcsCaptureFailed=true;
    source.viewUcsPending.clear();
    if(source.successful)finishViewUcsSources(data);
    if(!source.renderingPending.empty())source.renderingCaptureFailed=true;
    source.renderingPending.clear();
    if(source.successful)finishRenderingInputs(data);
    if(source.successful)finishRenderingSources(data);
    if(source.successful)finishLayoutRoleAudit(data);
    if(source.successful)finishEntitiesRoleAudit(data);
    for(auto& item:source.blockSources) {
        auto& row=item.second;
        if(row.publishedEndpoint||row.publishedEndpointRaw||row.publishedChildren||row.publishedDelivery||row.originPending)row.originFailed=true;
        row.publishedEndpoint=nullptr;row.publishedEndpointRaw=nullptr;row.publishedChildren=nullptr;row.publishedDelivery=nullptr;row.originPending=false;
    }
    if(source.successful)finishDxfBlockOriginAudits(data);
    if(source.successful)finishBlockRoleAudit(data);
    if(source.successful)finishTableReferences(data);
    if(source.successful)finishDependencies(data);
}

void dx_iface::addTableContent(const DRW_TableContentObject& data) {
    if (!cData) return;
    cData->standaloneTableContentPresent = true;
    if (!tableSourceCaptureOpen()) return;
    auto& source = cData->m_tableDxfSource;
    std::size_t bytes = 0u;
    if (!estimateTableContentSourceBytes(data, bytes)) { source.failed = true; return; }
    if (!chargeTableSource(bytes, 0u)) return;
    try {
        auto metadata=freezeTableSourceMetadata(data.m_dxfMetadata);
        const auto captured=source.contents.emplace(data.handle,data);
        if (!captured.second) source.failed=true;
        else captured.first->second.m_dxfMetadata=std::move(metadata);
    } catch (...) { source.failed = true; }
}

