void dx_iface::addRenderSettings(const DRW_RenderSettings& data) {
    observeRenderingInput(&data,nullptr);
    if (cData == nullptr || cData->renderSettingsCaptureFailed)
        return;
    if (cData->renderSettingsRetainedRecords
        >= kMaxAdapterRenderSettingsRecords) {
        cData->renderSettingsCaptureFailed = true;
        return;
    }

    std::size_t estimatedBytes = 0;
    std::size_t valueCount = 0;
    if (!estimateRenderSettingsTypedBytes(data, estimatedBytes, valueCount)
        || cData->renderSettingsRetainedValues
            > kMaxAdapterRenderSettingsValues
        || valueCount > kMaxAdapterRenderSettingsValues
                              - cData->renderSettingsRetainedValues
        || cData->renderSettingsRetainedBytes
            > kMaxAdapterRenderSettingsRetainedBytes
        || estimatedBytes > kMaxAdapterRenderSettingsRetainedBytes
                                - cData->renderSettingsRetainedBytes) {
        cData->renderSettingsCaptureFailed = true;
        return;
    }

    try {
        cData->renderSettings.push_back(data);
        ++cData->renderSettingsRetainedRecords;
        cData->renderSettingsRetainedValues += valueCount;
        cData->renderSettingsRetainedBytes += estimatedBytes;
    } catch (...) {
        cData->renderSettingsCaptureFailed = true;
    }
}

