void dx_iface::addCellStyleMap(const DRW_CellStyleMap& data) {
    retainTableResource(dx_tableResourceFamily::CellStyleMap,data);
    if (cData == nullptr || cData->cellStyleMapsCaptureFailed)
        return;
    const bool retainDxfBaseline =
        cData->sourceFormat == dx_source_format::DXF;
    if (cData->cellStyleMapsRetainedRecords
        >= kMaxAdapterCellStyleMapRecords) {
        cData->cellStyleMapsCaptureFailed = true;
        return;
    }

    std::size_t estimatedBytes = 0u;
    std::size_t itemCount = 0u;
    if (!estimateCellStyleMapTypedBytes(data, estimatedBytes, itemCount)
        || cData->cellStyleMapsRetainedItems
            > kMaxAdapterCellStyleMapItems
        || itemCount > kMaxAdapterCellStyleMapItems
                - cData->cellStyleMapsRetainedItems
        || cData->cellStyleMapsRetainedBytes
            > kMaxAdapterCellStyleMapRetainedBytes
        || estimatedBytes > kMaxAdapterCellStyleMapRetainedBytes
                - cData->cellStyleMapsRetainedBytes) {
        cData->cellStyleMapsCaptureFailed = true;
        return;
    }

    if (retainDxfBaseline) {
        const std::size_t retainedRecords =
            cData->cellStyleMapsRetainedRecords;
        const std::size_t baselineRecords =
            cData->m_cellStyleMapDxfBaselineRetainedRecords;
        const std::size_t retainedItems =
            cData->cellStyleMapsRetainedItems;
        const std::size_t baselineItems =
            cData->m_cellStyleMapDxfBaselineRetainedItems;
        const std::size_t retainedBytes =
            cData->cellStyleMapsRetainedBytes;
        const std::size_t baselineBytes =
            cData->m_cellStyleMapDxfBaselineRetainedBytes;
        const bool recordBudgetExceeded =
            retainedRecords > kMaxAdapterCellStyleMapRecords
            || baselineRecords > kMaxAdapterCellStyleMapRecords
                    - retainedRecords
            || kMaxAdapterCellStyleMapRecords - retainedRecords
                    - baselineRecords < 2u;
        const bool itemBudgetExceeded =
            retainedItems > kMaxAdapterCellStyleMapItems
            || baselineItems > kMaxAdapterCellStyleMapItems - retainedItems
            || itemCount > (kMaxAdapterCellStyleMapItems - retainedItems
                            - baselineItems) / 2u;
        const bool byteBudgetExceeded =
            retainedBytes > kMaxAdapterCellStyleMapRetainedBytes
            || baselineBytes > kMaxAdapterCellStyleMapRetainedBytes
                    - retainedBytes
            || estimatedBytes >
                (kMaxAdapterCellStyleMapRetainedBytes - retainedBytes
                 - baselineBytes) / 2u;
        if (recordBudgetExceeded || itemBudgetExceeded
            || byteBudgetExceeded) {
            cData->cellStyleMapsCaptureFailed = true;
            cData->m_cellStyleMapDxfBaselineCaptureFailed = true;
            return;
        }
    }

    bool typedRecordPushed = false;
    try {
        cData->cellStyleMaps.push_back(data);
        typedRecordPushed = true;
        if (retainDxfBaseline)
            cData->m_cellStyleMapDxfBaselines.push_back(data);
    } catch (...) {
        cData->cellStyleMapsCaptureFailed = true;
        if (retainDxfBaseline)
            cData->m_cellStyleMapDxfBaselineCaptureFailed = true;
        if (typedRecordPushed)
            cData->cellStyleMaps.pop_back();
        return;
    }
    ++cData->cellStyleMapsRetainedRecords;
    cData->cellStyleMapsRetainedItems += itemCount;
    cData->cellStyleMapsRetainedBytes += estimatedBytes;
    if (retainDxfBaseline) {
        ++cData->m_cellStyleMapDxfBaselineRetainedRecords;
        cData->m_cellStyleMapDxfBaselineRetainedItems += itemCount;
        cData->m_cellStyleMapDxfBaselineRetainedBytes += estimatedBytes;
    }
}

