void dx_iface::addMLineStyle(const DRW_MLineStyle& data) {
    if (cData == nullptr || cData->mLineStyleCaptureFailed
        || cData->namedResourceTypedCaptureFailed
        || cData->namedResourceTypedResourceLimitExceeded)
        return;
    dx_namedResourceImportReceipt& receipt = cData->namedResourceImport;
    if (cData->sourceFormat == dx_source_format::DXF
        && cData->importGeneration != 0u
        && receipt.generation != cData->importGeneration) {
        cData->mLineStyleCaptureFailed = true;
        failNamedResourceTypedCapture(*cData, false);
        return;
    }
    if (cData->mLineStyleRetainedRecords
            >= kMaxAdapterMLineStyleRecords) {
        cData->mLineStyleCaptureFailed = true;
        failNamedResourceTypedCapture(*cData, true);
        return;
    }

    std::size_t estimatedBytes = 0u;
    std::size_t itemCount = 0u;
    if (!estimateMLineStyleTypedBytes(data, estimatedBytes, itemCount)
        || cData->mLineStyleRetainedItems > kMaxAdapterMLineStyleItems
        || itemCount > kMaxAdapterMLineStyleItems
                            - cData->mLineStyleRetainedItems
        || cData->mLineStyleRetainedBytes
            > kMaxAdapterMLineStyleRetainedBytes
        || estimatedBytes > kMaxAdapterMLineStyleRetainedBytes
                                - cData->mLineStyleRetainedBytes) {
        cData->mLineStyleCaptureFailed = true;
        failNamedResourceTypedCapture(*cData, true);
        return;
    }
    if (!admitNamedResourceTypedCopy(*cData, estimatedBytes)) {
        cData->mLineStyleCaptureFailed = true;
        return;
    }

    try {
        cData->mLineStyles.push_back(data);
    } catch (...) {
        cData->mLineStyleCaptureFailed = true;
        failNamedResourceTypedCapture(*cData, false);
        return;
    }
    ++cData->mLineStyleRetainedRecords;
    cData->mLineStyleRetainedItems += itemCount;
    cData->mLineStyleRetainedBytes += estimatedBytes;
    ++cData->namedResourceTypedRetainedRecords;
    cData->namedResourceTypedRetainedBytes += estimatedBytes;
}

