void dx_iface::addField(const DRW_Field& data) {
    retainTableResource(dx_tableResourceFamily::Field,data);
    observeResourceOrigin(&data,nullptr);
    constexpr std::size_t listNodeLinkBytes = 2u * sizeof(void*);
    if (cData == nullptr || cData->fieldCarrierTypedCaptureFailed)
        return;
    dx_fieldCarrierImportReceipt& receipt = cData->fieldCarrierImport;
    const bool trackedImport = cData->sourceFormat == dx_source_format::DXF
        && cData->importGeneration != 0u
        && receipt.generation == cData->importGeneration;
    const auto reject = [&](bool resourceLimit) {
        cData->fieldCarrierTypedCaptureFailed = true;
        if (trackedImport || cData->sourceFormat == dx_source_format::DXF) {
            receipt.typedResourceLimitExceeded =
                receipt.typedResourceLimitExceeded || resourceLimit;
            receipt.typedCaptureFailed =
                receipt.typedCaptureFailed || !resourceLimit;
        }
    };
    if (cData->sourceFormat == dx_source_format::DXF
        && cData->importGeneration != 0u && !trackedImport) {
        reject(false);
        return;
    }
    if (cData->fieldCarrierTypedRetainedRecords
            >= kMaxAdapterFieldTypedRecords
        || (trackedImport
            && receipt.typedCallbacks >= kMaxAdapterFieldTypedRecords)) {
        reject(true);
        return;
    }

    std::size_t estimatedBytes = 0u;
    std::size_t itemCount = 0u;
    if (!estimateFieldTypedBytes(data, estimatedBytes, itemCount)
        || estimatedBytes > kMaxAdapterFieldTypedRetainedBytes
                                - listNodeLinkBytes) {
        reject(true);
        return;
    }
    estimatedBytes += listNodeLinkBytes;
    if (cData->fieldCarrierTypedItemCount
            > kMaxAdapterFieldTypedItems
        || itemCount > kMaxAdapterFieldTypedItems
                            - cData->fieldCarrierTypedItemCount
        || cData->fieldCarrierTypedRetainedBytes
            > kMaxAdapterFieldTypedRetainedBytes
        || estimatedBytes > kMaxAdapterFieldTypedRetainedBytes
                                - cData->fieldCarrierTypedRetainedBytes
        || (trackedImport
            && (receipt.typedItemCount > kMaxAdapterFieldTypedItems
                || itemCount > kMaxAdapterFieldTypedItems
                                  - receipt.typedItemCount
                || receipt.typedRetainedBytes
                    > kMaxAdapterFieldTypedRetainedBytes
                || estimatedBytes > kMaxAdapterFieldTypedRetainedBytes
                                      - receipt.typedRetainedBytes))) {
        reject(true);
        return;
    }

    try {
        cData->fields.push_back(data);
        ++cData->fieldCarrierTypedRetainedRecords;
        cData->fieldCarrierTypedItemCount += itemCount;
        cData->fieldCarrierTypedRetainedBytes += estimatedBytes;
        if (trackedImport) {
            ++receipt.typedCallbacks;
            receipt.typedItemCount += itemCount;
            receipt.typedRetainedBytes += estimatedBytes;
        }
    } catch (...) {
        reject(false);
    }
}

